(window.NTDATA=window.NTDATA||{});(NTDATA.cass=NTDATA.cass||{}).lk={"1":{"1":"Так как уже многие взялись за составление\nповествования о совершившихся среди нас событиях,","2":"как передали нам те, кому от начала довелось\nбыть очевидцами и служителями слова,","3":"решил и я, тщательно исследовав все с самого\nначала,\nпоследовательно\nнаписать\nдля\nтебя,\nпревосходнейший Феофил,","4":"чтобы ты познал достоверность того учения, в\nкотором был наставлен.","5":"Был в дни Ирода, царя Иудейского, некий\nсвященник по имени Захария, из чреды Авиевой, и жена\nу него из дочерей Аароновых, имя ее Елисавета.","6":"Были же праведны они оба пред Богом, поступая\nпо\nвсем\nзаповедям\nи\nуставам\nГосподним\nбезукоризненно.","7":"И были они бездетны, ибо Елисавета была\nнеплодна, и оба достигли преклонного возраста.","8":"Было же: когда священнодействовал он в порядке\nчреды своей пред Богом, по обычаю священного\nслужения,","9":"выпал ему жребий воскурить фимиам, войдя в\nхрам Господень;","10":"а все множество народа молилось вне во время\nкаждения.","11":"Явился же ему ангел Господень, став по правую\nсторону жертвенника кадильного.","12":"И смущен был Захария этим видением, и страх\nнапал на него.","13":"Сказал же ему ангел: не бойся, Захария, ибо\nуслышана молитва твоя, и жена твоя Елисавета родит\nтебе сына, и наречешь имя ему: Иоанн.","14":"И будет радость тебе и ликование, и многие о\nрождении его возрадуются;","15":"ибо он будет велик пред Господом, и вина и\nхмельного не будет пить, и Духа Святого исполнится\nеще от чрева матери своей,","16":"и многих из сынов Израилевых обратит к Господу\nБогу их.","17":"Он будет идти перед Ним в духе и силе Илии,\nчтобы возвратить сердца отцов детям и непокорным\nобраз мыслей праведных, представить Господу народ\nприготовленный.","18":"И сказал Захария ангелу: по какому знаку узнаю\nя это? Я ведь стар, и жена моя достигла преклонного\nвозраста.","19":"И ответил ему ангел: я Гавриил, предстоящий\nпред Богом, и послан говорить тебе и благовествовать\nтебе это.","20":"И вот, ты будешь молчать и не сможешь говорить\nдо того дня, когда сбудется это, за то, что ты не\nповерил словам моим, которые исполнятся в свое время.","21":"И\nожидал\nнарод\nЗахарию\nи\nудивлялся\nпромедлению его в храме.","22":"А выйдя, он не мог с ними говорить, и поняли\nони, что он имел видение в храме; и сам он делал им\nзнаки и оставался нем.","23":"И было: когда окончились дни служения его,\nушел он в дом свой.","24":"После же этих дней зачала Елисавета, жена его,\nи пять месяцев скрывала себя от всех, говоря:","25":"так мне сотворил Господь в дни, когда Ему\nугодно было снять с меня поношение среди людей.","26":"В шестой же месяц послан был ангел Гавриил от\nБога в город Галилейский, по имени Назарет,","27":"к деве, обрученной мужу по имени Иосиф, из\nдома Давидова; и имя девы – Мариам.","28":"И\nвойдя\nк\nНей,\nангел\nсказал:\nрадуйся,\nБлагодатная! Господь с Тобою!","29":"Она же была смущена этой речью и размышляла:\nчто же это за приветствие?","30":"И сказал Ей ангел: не бойся, Мариам, ибо Ты\nобрела благодать у Бога.","31":"И вот, Ты зачнешь во чреве и родишь Сына и\nнаречешь имя Ему: Иисус.","32":"Он будет велик, и Сыном Всевышнего будет\nназван, и даст Ему Господь Бог престол Давида, отца\nЕго,","33":"и будет царствовать над домом Иакова вовеки, и\nЦарству Его не будет конца.","34":"Сказала же Мариам ангелу: как же будет это, раз\nЯ мужа не знаю?","35":"И ответил Ей ангел: Дух Святой найдет на Тебя, и\nсила Всевышнего осенит Тебя; потому и рождаемое\nСвятое названо будет Сыном Божиим.","36":"И вот Елисавета, родственница Твоя, и та зачала\nсына в старости своей, и этот месяц уже шестой для\nнее, которую называют неплодной,","37":"ибо у Бога не останется бессильным никакое\nслово.","38":"Сказала же Мариам: вот – раба Господня; да\nбудет Мне по слову твоему. И отошел от Нее ангел.","39":"В эти дни Мариам, отправившись в путь, пошла с\nпоспешностью в горную страну, в город Иудин,","40":"и вошла в дом Захарии и приветствовала\nЕлисавету.","41":"И было: когда услышала Елисавета приветствие\nМарии, вострепетал младенец во чреве ее; и Елисавета\nисполнилась Духа Святого,","42":"и воскликнула громким голосом и сказала:\nблагословенна Ты в женах, и благословен плод чрева\nТвоего!","43":"И откуда это мне, что Мать Господа моего\nпришла ко мне?","44":"Ибо когда прозвучал голос приветствия Твоего в\nушах моих, вострепетал в ликовании младенец во чреве\nмоем,","45":"и\nблаженна\nПоверившая,\nчто\nсовершится\nсказанное Ей от Господа.","46":"И сказала Мариам: Величает душа Моя Господа,","47":"и возликовал дух Мой о Боге, Спасителе Моем,","48":"что призрел Он на малость рабы Своей; ибо\nотныне будут называть Меня блаженной все роды;","49":"что сотворил Мне великое Сильный, и свято имя\nЕго,","50":"и милость Его в роды и роды боящимся Его;","51":"соделал Он сильное рукою Своею, рассеял\nгордых в помышлениях сердца их;","52":"низложил властителей с престолов и возвысил\nсмиренных;","53":"алчущих преисполнил благ; и богатых отослал ни\nс чем;","54":"поддержал Израиля, отрока Своего, в память о\nмилости –","55":"как Он сказал отцам нашим, – милости к Аврааму\nи семени его вовек.","56":"Пробыла же Мариам с ней около трех месяцев и\nвозвратилась в дом Свой.","57":"Елисавете же настало время родить, и она\nродила сына,","58":"и услышали соседи и родственники ее, что\nумножил Господь милость Свою к ней, и радовались с\nнею.","59":"И было: в день восьмой пришли обрезать дитя, и\nхотели назвать его, по имени отца его, Захарией.","60":"И мать его ответила: нет, но будет он назван\nИоанном.","61":"И сказали ей: никого нет из родни твоей, кто\nназывался бы этим именем;","62":"и начали знаками задавать отцу его вопрос, как\nхотел бы он, чтобы называли его.","63":"И попросив дощечку, он написал так: Иоанн – имя\nему. И удивились все.","64":"И тотчас открылись уста его и язык, и он\nговорил, благословляя Бога.","65":"И был страх у всех живущих вокруг них, и по\nвсей горной стране Иудейской шла молва о всём этом.","66":"И все слышавшие положили это на сердце свое и\nговорили: что же будет дитя это? Ибо рука Господня\nбыла с ним.","67":"И Захария, отец его, исполнился Духа Святого и\nпророчествовал, говоря:","68":"Благословен Господь Бог Израилев, что посетил\nи сотворил искупление народу Своему,","69":"и воздвиг нам рог спасения в доме Давида,\nотрока Своего, –","70":"как Он сказал устами святых древних пророков\nСвоих, –","71":"спасение от врагов наших и от руки всех\nненавидящих нас:","72":"сотворить милость отцам нашим и вспомнить\nзавет Свой святой,","73":"клятву, которою Он клялся Аврааму, отцу\nнашему,","74":"чтобы\nбезбоязненно,\nизбавившись\nот\nруки\nврагов,","75":"служили мы Ему в святости и праведности, все\nдни наши пред Ним.","76":"И ты, дитя, пророком Всевышнего будешь\nназвано,\nибо\nты\nбудешь\nидти\nпред\nНим,\nчтобы\nприготовить пути Ему,","77":"дать народу Его познать спасение в отпущении\nгрехов их,","78":"по глубине милосердия Бога нашего, которым с\nвысоты посетит нас Восходящее Светило,","79":"воссиять сидящим во тьме и тени смерти,\nнаправить ноги наши на путь мира.","80":"Дитя же возрастало и укреплялось духом. И был\nон в пустынях до дня явления его пред Израилем."},"2":{"1":"Было же в дни те: вышел указ от кесаря Августа о\nпереписи всей вселенной","2":"Это была первая перепись в правление Квириния\nСирией.","3":"И шли все записываться, каждый в свой город.","4":"И пошел также Иосиф из Галилеи из города\nНазарета в Иудею в город Давидов, называемый\nВифлеем, потому что был он из дома и рода Давидова,","5":"записаться с Мариам, обрученною ему, которая\nбыла беременна.","6":"Было же: пока они находились там, исполнились\nдни, когда Она должна была родить,","7":"и родила Она Сына Своего первенца и спеленала\nЕго и положила Его в яслях, потому что не было им\nместа в гостинице.","8":"И были в этой стране пастухи, жившие под\nоткрытым небом и стерегшие ночью стадо свое.","9":"И ангел Господень предстал им, и слава Господня\nосияла их, и они устрашились страхом великим.","10":"И сказал им ангел: не бойтесь. Ибо вот,\nблаговествую вам радость великую, которая будет\nвсему народу:","11":"родился вам сегодня в городе Давидовом\nСпаситель, Который есть Христос Господь.","12":"И вот вам знамение: вы найдете Младенца\nспелёнатого и лежащего в яслях.","13":"И внезапно вместе с ангелом явилось множество\nвоинства небесного, хваля Бога и говоря:","14":"Слава в вышних Богу, и на земле мир, в людях\nблаговоление.","15":"И было: когда отошли от них на небо ангелы,\nпастухи стали говорить друг другу: дойдем же до\nВифлеема и посмотрим, что такое произошло, о чем\nГосподь объявил нам.","16":"И они поспешили придти, и нашли и Мариам, и\nИосифа, и Младенца, лежащего в яслях.","17":"Увидев же, сообщили о том, что им сказано было\nоб Этом Дитяти.","18":"И все услышавшие удивились сказанному им\nпастухами.","19":"Мариам же все слова эти сохраняла, слагая в\nсердце Своем.","20":"И возвратились пастухи, славя и хваля Бога за\nвсё, что они увидели и услышали так, как было сказано\nим.","21":"И\nкогда\nисполнилось\nвосемь\nдней,\nчтобы\nобрезать Его, тогда и наречено было имя Ему: Иисус,\nданное ангелом прежде зачатия Его во чреве.","22":"И когда исполнились дни очищения их по Закону\nМоисееву, принесли Его в Иерусалим, чтобы поставить\nпред Господом,","23":"как написано в Законе Господнем: «Всякое\nсущество мужеского пола, разверзающее материнскую\nутробу, да будет посвящено Господу»,","24":"и чтобы принести жертву по сказанному в Законе\nГосподнем: пару горлиц или двух птенцов голубиных.","25":"И вот, был в Иерусалиме человек, которому имя\nСимеон,\nчеловек\nправедный\nи\nблагоговейный,\nожидающий утешения Израиля, и Дух Святой был на\nнем.","26":"И было ему открыто Духом Святым, что он не\nувидит смерти, прежде чем не увидит Христа Господня.","27":"И пришел он в Духе в храм, и когда принесли\nродители Младенца Иисуса, чтобы совершить над Ним\nустановленное по Закону,","28":"он взял Его на руки, благословил Бога и сказал:","29":"Теперь отпускаешь Ты раба Твоего, Владыко, по\nслову Твоему, с миром,","30":"ибо видели очи мои спасение Твое,","31":"которое Ты уготовал пред лицом всех народов:","32":"свет во откровение язычникам, и славу народа\nТвоего Израиля.","33":"И отец Его и Мать удивлялись тому, что\nговорилось о Нем.","34":"И благословил их Симеон и сказал Мариам,\nМатери Его: вот, Он лежит на падение и восстание\nмногих во Израиле и в знамение прорекаемое,","35":"и Тебе же Самой душу пройдет меч, чтобы\nраскрыты были во многих сердцах помышления.","36":"И была Анна пророчица, дочь Фануила, из колена\nАсирова. Она достигла весьма преклонного возраста,\nпрожив с мужем семь лет от девства своего,","37":"и вдовой до восьмидесяти четырех лет. Она не\nотходила от храма, постом и молитвою служа Богу день\nи ночь.","38":"И в этот час, подойдя, она славила Бога и\nговорила\nо\nНем\nвсем\nожидающим\nискупления\nИерусалима.","39":"И когда они совершили всё положенное по\nЗакону Господню, то возвратились в Галилею в город\nсвой Назарет.","40":"Дитя же росло и укреплялось, исполняясь\nпремудрости, и благодать Божия была на Нем.","41":"И ходили родители Его каждый год в Иерусалим\nна праздник Пасхи.","42":"И по достижении Им двенадцати лет, когда\nвосходили они в Иерусалим по обычаю Праздника,","43":"и\nсовершили\nположенные\nдни,\n–\nпри\nвозвращении остался Отрок Иисус в Иерусалиме, и не\nзаметили этого родители Его.","44":"Думая же, что Он со спутниками, прошли они\nдневной путь и стали искать Его среди родственников и\nзнакомых,","45":"и не найдя, возвратились в Иерусалим, ища Его.","46":"И было: через три дня нашли они Его в храме,\nсидящего\nмежду\nучителями\nи\nслушающего\nих\nи\nзадающего им вопросы;","47":"и изумлялись все слушающие Его разуму и\nответам Его.","48":"И увидев Его, они были поражены, и сказала Ему\nМатерь Его: Дитя Мое, почему поступил Ты с нами так?\nВот, отец Твой и Я с болью ищем Тебя.","49":"И сказал Он им: что же вы искали Меня? Не знали\nвы, что Мне надлежит быть во владениях Отца Моего?","50":"И они не поняли слова, которое Он сказал им.","51":"И Он ушел с ними и пришел в Назарет, и был в\nповиновении у них, и Матерь Его хранила всё это в\nсердце Своем.","52":"А Иисус преуспевал в премудрости и возрасте и\nлюбви у Бога и людей."},"3":{"1":"В пятнадцатый же год правления Тиверия кесаря,\nкогда Понтий Пилат управлял Иудеей, и тетрархом\nГалилеи был Ирод, Филипп же, брат его, был тетрархом\nИтуреи\nи\nТрахонитской\nобласти,\nи\nЛисаний\nбыл\nтетрархом Авилинеи,","2":"при первосвященнике Анне и Каиафе, было слово\nБожие к Иоанну, сыну Захарии, в пустыне.","3":"И прошел он всю страну Иорданскую, проповедуя\nкрещение покаяния для отпущения грехов,","4":"как написано в книге слов Исаии пророка: Голос\nвопиющего в пустыне: «приготовьте дорогу Господу,\nпрямыми делайте пути Его:","5":"всякий овраг наполнится, и всякая гора и холм\nснизится, и станет кривое прямыми путями, и неровные\nтропы – дорогами гладкими,","6":"и увидит всякая плоть спасение Божие».","7":"Итак, он говорил народу, выходившему креститься\nу него: отродье змеиное, кто указал вам бежать от\nбудущего гнева?","8":"Сотворите же плоды достойные покаяния, и не\nначинайте говорить самим себе: «отец у нас Авраам»,\nибо говорю вам, что может Бог из камней этих\nвоздвигнуть детей Аврааму.","9":"Уже лежит и топор при корне деревьев: итак,\nвсякое\nдерево,\nне\nприносящее\nдоброго\nплода,\nсрубается и бросается в огонь,","10":"И спрашивал его народ, говоря: что нам делать?","11":"Он же отвечал им: у кого две рубашки, пусть\nподелится с неимущим, и у кого есть пища, пусть так\nже поступает.","12":"Пришли же и мытари креститься и сказали ему:\nУчитель, что нам делать?","13":"Он же сказал им: ничего больше положенного\nвам не взыскивайте.","14":"Спрашивали его и воины, говоря: а нам что\nделать?\nИ\nсказал\nим:\nникого\nне\nнасилуйте,\nне\nвымогайте\nдоносами\nи\nдовольствуйтесь\nсвоим\nжалованьем.","15":"И ждал народ, и размышляли все в сердцах своих\nоб Иоанне: а не Христос ли он сам?","16":"И ответил Иоанн, обращаясь ко всем: я водою\nкрещу вас; идет же Сильнейший меня, у Которого я\nнедостоин развязать ремень обуви Его. Он будет\nкрестить вас Духом Святым и огнем.","17":"Лопата Его в руке Его, чтобы очистить гумно\nСвое и собрать пшеницу в житницу Свою, а мякину Он\nсожжет огнем неугасимым.","18":"И многое иное внушал он народу, благовествуя\nему.","19":"Ирод же тетрарх, обличаемый им за Иродиаду,\nжену брата своего, и за всё, что он сделал дурного,","20":"прибавил ко всему прочему и то, что заключил\nИоанна в тюрьму.","21":"И было: когда крестился весь народ, и Иисус\nкрестившись молился, открылось небо,","22":"и нисшел Дух Святой в телесном виде, как\nголубь, на Него, и голос с неба раздался: Ты Сын Мой\nвозлюбленный, на Тебе Мое благоволение.","23":"И Сам Иисус, начиная Свое служение, был лет\nтридцати; Он, как думали, был сын Иосифа, Илия,","24":"Матфата, Левия, Мелхия, Ианная, Иосифа,","25":"Маттафии, Амоса, Наума, Еслия, Наггея,","26":"Маафа, Маттафии, Семеина, Иосиха, Иодая,","27":"Иоанана, Рисая, Зоровавеля, Салафиила, Нирия,","28":"Мелхия, Аддия, Косама, Елмадама, Ира,","29":"Иисуса, Елиезера, Иорима, Матфата, Левия,","30":"Симеона, Иуды, Иосифа, Ионама, Елиакима,","31":"Мелеая, Менная, Маттафая, Нафана, Давида,","32":"Иессея, Овида, Вооса, Салы, Наассона,","33":"Аминадава, Админа, Арния, Есрома, Фареса,\nИуды,","34":"Иакова, Исаака, Авраама, Фары, Нахора,","35":"Серуха, Рагава, Фалека, Евера, Салы,","36":"Каинана, Арфаксада, Сима, Ноя, Ламеха,","37":"Мафусала, Еноха, Иарета, Малелеила, Каинана,","38":"Еноса, Сифа, Адама, Бога."},"4":{"1":"Иисус же, полный Духа Святого, возвратился с\nИордана и водим был Духом в пустыне","2":"в течение сорока дней, искушаемый диаволом, и\nне ел ничего в дни те. И по окончании их, ощутил голод.","3":"И сказал Ему диавол: если Ты Сын Божий, скажи\nкамню этому, чтобы он сделался хлебом.","4":"И ответил ему Иисус: написано: «Не хлебом одним\nжив будет человек».","5":"И возведя Его, показал Ему все царства вселенной\nво мгновение времени.","6":"И сказал Ему диавол: Тебе дам всю эту власть и\nславу их, потому что мне предана она, и я, кому хочу,\nдаю ее.","7":"Вот и Ты, если поклонишься мне, всё будет Твое.","8":"И ответил ему Иисус: написано: «Поклоняйся\nГосподу Богу твоему и Ему одному служи».","9":"И повел он Его в Иерусалим и поставил на крыло\nхрама и сказал Ему: если Ты Сын Божий, бросься отсюда\nвниз.","10":"Написано, ведь: «Ангелам Своим заповедует Он о\nТебе сохранить Тебя»,","11":"И: «На руках понесут Тебя, чтобы Ты не\nпреткнулся о камень ногою Твоею».","12":"И ответил ему Иисус: сказано: «Не искушай\nГоспода Бога твоего».","13":"И окончив всё искушение, диавол отошел от Него\nдо времени.","14":"И возвратился Иисус в силе Духа в Галилею, и\nмолва о Нем прошла по всей стране,","15":"и учил Он в синагогах их, прославляемый всеми.","16":"И пришел Он в Назарет, где был воспитан, и\nвошел, по обыкновению Своему, в день субботний в\nсинагогу, и встал, чтобы читать.","17":"И подали Ему книгу пророка Исаии, и открыв\nкнигу, Он нашел место, где было написано:","18":"Дух Господа на Мне, ибо Он помазал Меня.\nПослал\nМеня\nблаговествовать\nнищим,\nвозвестить\nпленным освобождение и слепым прозрение, отпустить\nугнетенных на свободу,","19":"возвестить лето милости Господней.","20":"И закрыв книгу, отдав служителю, Он сел; и\nглаза всех в синагоге были устремлены на Него;","21":"и Он начал говорить им: ныне исполнилось\nписание это перед вами.","22":"И все свидетельствовали Ему и удивлялись\nсловам благодати, исходившим из уст Его, и говорили:\nне сын ли Он Иосифа?","23":"И Он сказал им: конечно, вы скажете Мне эту\nпословицу: «врач, исцели самого себя: сделай и здесь, в\nотечестве Твоем, то, что, мы слышали, произошло в\nКапернауме».","24":"И Он сказал: истинно говорю вам: ни один пророк\nне бывает принят в отечестве своем.","25":"Поистине же говорю вам: много было вдов во дни\nИлии в Израиле, когда заключено было небо три года и\nшесть месяцев, так что сделался голод великий по всей\nземле,","26":"и ни к одной из них не был послан Илия, а только\nв Сарепту Сидонскую к женщине-вдове;","27":"и много было прокаженных в Израиле при Елисее\nпророке, и ни один из них не был очищен, а только\nНееман Сириец.","28":"И исполнились все ярости в синагоге, услышав\nэто,","29":"и встав, выгнали Его вон из города, и повели до\nобрыва горы, на которой построен их город, чтобы\nсбросить Его.","30":"Он же, пройдя посреди них, пошел Своим путем.","31":"И спустился в Капернаум, город Галилейский; и\nучил их в субботу,","32":"и они изумлялись учению Его, ибо слово Его было\nс властью.","33":"И в синагоге был человек, имевший духа, беса\nнечистого, и он вскричал громким голосом:","34":"О! Что Тебе до нас, Иисус Назарянин? Ты пришел\nпогубить нас! Знаю Тебя, кто Ты, Святой Божий.","35":"И строго сказал ему Иисус: замолчи и выйди из\nнего. И повергнув его посредине, бес вышел из него,\nничуть не повредив ему.","36":"И напал ужас на всех, и говорили они между\nсобой: что это за слово, которым Он с властью и силой\nповелевает нечистым духам, и они выходят?","37":"И расходилась молва о Нем повсюду в окрестной\nстране.","38":"Встав же и выйдя из синагоги, Он вошел в дом\nСимона. Теща же Симона была одержима сильной\nгорячкой, и попросили Его о ней.","39":"И став над ней, Он запретил горячке, и та\nоставила ее. И она, тотчас встав, служила им.","40":"На закате же солнца все, у кого были больные\nразличными недугами, привели их к Нему. А Он,\nвозлагая руки на каждого из них, исцелял их.","41":"Выходили же и бесы из многих с криком и\nговорили: Ты – Сын Божий. И обращаясь к ним со всею\nстрогостью, Он не позволял им говорить, так как они\nзнали, что Он – Христос.","42":"С наступлением же дня, Он, выйдя, направился в\nпустынное место, и народ искал Его и нашел Его, и\nудерживал, чтобы Он не уходил от них.","43":"Он же сказал им: и другим городам должен Я\nблаговествовать Царство Божие, потому что для этого Я\nпослан.","44":"И проповедывал в синагогах Иудеи."},"5":{"1":"Было же: когда толпа теснила Его и слушала\nслово Божие, и Сам Он стоял у озера Геннисаретского, –","2":"увидел Он две лодки, стоящие на озере. А рыбаки,\nвыйдя из них, мыли сети.","3":"Войдя же в одну из лодок, которая принадлежала\nСимону, Он попросил его отойти немного от берега; и\nсев, учил из лодки народ.","4":"Когда же Он перестал говорить, то сказал Симону:\nотойди на глубину и закиньте сети ваши для лова.","5":"И ответил Симон: Наставник, всю ночь мы\nтрудились и ничего не поймали. Но по слову Твоему,\nзакину сети.","6":"И сделав это, они захватили многое множество\nрыб; и сети их прорывались.","7":"И они сделали знак товарищам на другой лодке,\nчтобы пришли к ним на помощь; и те подошли и\nнаполнили обе лодки, так что они погружались в воду.","8":"Увидев это, Симон Петр припал к коленям Иисуса\nи сказал: уйди от меня, Господи, ибо я муж грешный.","9":"От этого улова рыб, ими пойманных, ужас объял\nего и всех с ним бывших,","10":"а также и Иакова и Иоанна, сыновей Зеведеевых,\nкоторые были товарищами Симона. И сказал Симону\nИисус: не бойся; отныне будешь уловлять людей.","11":"И вытащив лодки на землю, они оставили всё и\nпоследовали за Ним.","12":"И было: когда находился Он в одном из городов,\nто пришел человек весь в проказе. Увидев же Иисуса, он\nпал на лицо и попросил Его: Господи, если Ты хочешь,\nможешь меня очистить.","13":"И протянув руку, Он коснулся его, говоря: хочу,\nочистись. И тотчас проказа сошла с него.","14":"И Он повелел ему никому не говорить, но сказал:\nпойди, покажись священнику и принеси за очищение\nтвое, как повелел Моисей, во свидетельство им.","15":"Распространялась же всё больше молва о Нем, и\nсходилось много народа слушать и исцеляться от\nболезней своих.","16":"Он же удалялся в пустынные места и молился.","17":"И было однажды: Сам Он учил, и сидели фарисеи\nи законоучители, пришедшие из всех селений Галилеи и\nиз Иудеи и Иерусалима, и сила Господня была в\nтворимых Им исцелениях, –","18":"и вот, люди несут на постели человека в\nпараличе. И они старались внести его и положить перед\nНим,","19":"и не найдя, каким путем внести его из-за толпы,\nони, поднявшись на крышу, через черепицу спустили\nего, вместе с постелью, на середину перед Иисусом.","20":"И увидев веру их, Он сказал: человек, прощены\nтебе грехи твои.","21":"И начали рассуждать книжники и фарисеи,\nговоря: кто это? Он богохульствует. Кто может простить\nгрехи, кроме одного только Бога?","22":"Иисус же, узнав рассуждения их, сказал им в\nответ: что рассуждаете в сердцах ваших?","23":"Что легче? Сказать ли: «прощены тебе грехи\nтвои», или сказать: «встань и ходи»?","24":"Но чтобы вы знали, что Сын Человеческий власть\nимеет\nна\nземле\nпрощать\nгрехи,\n–\nОн\nсказал\nпараличному: тебе говорю: «встань и, взяв постель\nтвою, ступай в дом твой».","25":"И он тотчас, встав перед ними, взяв то, на чем\nлежал, пошел в дом свой, славя Бога.","26":"И изумление объяло всех, и славили Бога и в\nстрахе говорили: дивное видели мы сегодня.","27":"И после этого Он вышел и увидел мытаря по\nимени Левия, сидящего у сбора пошлин, и сказал ему:\nследуй за Мною.","28":"И оставив всё, он встал и следовал за Ним.","29":"И сделал для Него Левий угощение великое в\nдоме своем, и была большая толпа мытарей и других,\nкоторые с Ним возлежали,","30":"И роптали фарисеи и книжники их, обращаясь к\nученикам Его: почему вы едите и пьете с мытарями и\nгрешниками?","31":"И ответил им Иисус: не здравствующим нужен\nврач, а болящим.","32":"Я пришел призвать не праведных, но грешных к\nпокаянию.","33":"Они же сказали Ему: ученики Иоанновы постятся\nчасто и молитвы творят, также и фарисейские; а Твои\nедят и пьют.","34":"Иисус же сказал им: можете ли вы заставить\nпоститься сынов чертога брачного, когда с ними\nЖених?","35":"Но придут дни, и когда взят будет от них Жених,\nтогда будут поститься, в те дни.","36":"Сказал же им и притчу: никто не ставит заплату\nна одежду ветхую, оторвав от одежды новой: иначе и\nновую разорвет и к ветхой не подойдет заплата от\nновой.","37":"И никто не наливает вино молодое в мехи\nветхие; иначе прорвет вино молодое мехи, и само\nвытечет, и мехи пропадут:","38":"но вино молодое надо наливать в мехи новые.","39":"И никто, испив старого, не захочет молодого, ибо\nговорит: «старое хорошо»."},"6":{"1":"Случилось в субботу проходить Ему засеянными\nполями; и срывали ученики Его и ели колосья, растирая\nруками.","2":"Некоторые же из фарисеев сказали: почему вы\nделаете то, чего нельзя делать в субботу?","3":"И ответил им Иисус: и о том вы не читали, что\nсделал Давид, когда проголодался сам и бывшие с ним?","4":"Что вошел он в дом Божий и взял хлебы\nпредложения, и ел и дал сопровождавшим его, – а их\nнельзя есть никому, кроме одних только священников?","5":"И говорил им: Сын Человеческий есть господин\nсубботы.","6":"Случилось же в другую субботу войти Ему в\nсинагогу и учить; и был там человек, и правая рука его\nбыла суха.","7":"Наблюдали же за Ним книжники и фарисеи, не\nисцеляет ли Он в субботу, чтобы найти обвинение\nпротив Него.","8":"Но Он знал помышления их и сказал мужу с сухою\nрукой: подымись и стань посредине. И он поднялся и\nстал.","9":"Сказал же им Иисус: спрашиваю вас: дозволяется\nли в субботу добро сделать или зло? Спасти душу или\nпогубить?","10":"И обведя взором всех их, сказал ему: протяни\nруку твою. Он сделал так, и восстановилась рука его.","11":"Они же пришли в бешенство и обсуждали между\nсобой, что бы им сделать с Иисусом.","12":"Случилось же Ему в те дни уйти на гору\nпомолиться, и Он проводил ночь в молитве к Богу,","13":"и когда настал день, Он позвал учеников Своих и\nизбрал из них двенадцать, которых и наименовал\nапостолами:","14":"Симона, которого и наименовал Петром, и\nАндрея, брата его, и Иакова, и Иоанна, и Филиппа, и\nВарфоломея,","15":"и Матфея, и Фому, и Иакова Алфеева, и Симона,\nназываемого Зилотом,","16":"и Иуду Иаковлева, и Иуду Искариота, который\nсделался предателем.","17":"И спустившись с ними, Он стал на ровном месте,\nи большая толпа учеников Его и великое множество\nнарода из всей Иудеи и Иерусалима и с побережья Тира\nи Сидона.","18":"Они пришли послушать Его и исцелиться от\nболезней\nсвоих.\nИ\nмучимые\nдухами\nнечистыми\nисцелялись.","19":"И вся толпа старалась прикасаться к Нему,\nпотому что сила от Него исходила и исцеляла всех.","20":"И Он, подняв глаза Свои на учеников Своих,\nговорил: Блаженны нищие, ибо ваше есть Царство\nБожие.","21":"Блаженны\nалчущие\nныне,\nибо\nвы\nбудете\nнасыщены.\nБлаженны\nплачущие\nныне,\nибо\nвы\nвоссмеетесь.","22":"Блаженны вы, когда будут ненавидеть вас люди,\nи когда будут отлучать вас, и поносить вас, и извергнут\nимя ваше, как злое, из-за Сына Человеческого.","23":"Возрадуйтесь в тот день и возликуйте, ибо вот,\nнаграда ваша велика на небе: ибо так поступали с\nпророками отцы их.","24":"Но горе вам, богатые, ибо вы получили утешение\nваше.","25":"Горе вам, пресыщенные ныне, ибо взалчете. Горе\nвам, смеющиеся ныне, ибо восплачете и возрыдаете.","26":"Горе вам, когда скажут о вас хорошо все люди.\nИбо так поступали с лжепророками отцы их.","27":"Но вам, слушающим, говорю: любите врагов\nваших, делайте добро ненавидящим вас,","28":"благословляйте проклинающих вас и молитесь за\nоскорбляющих вас.","29":"Ударяющему тебя в щеку подставь и другую, и\nотнимающему у тебя верхнюю одежду не откажи и в\nрубашке.","30":"Всякому\nпросящему\nу\nтебя\nдавай\nи\nот\nотнимающего твое не требуй обратно.","31":"И как хотите, чтобы поступали с вами люди, так\nпоступайте и вы с ними.","32":"И если любите любящих вас, какая вам за то\nблагодарность? Ведь и грешники любящих их любят,","33":"Ибо если вы делаете добро делающим вам добро,\nкакая вам благодарность? Ибо и грешники то же самое\nделают.","34":"И если взаймы даете тем, от кого надеетесь\nполучить,\nкакая\nвам\nблагодарность?\nИ\nгрешники\nгрешникам дают взаймы, чтобы получить обратно\nстолько же.","35":"Но вы любите врагов ваших и делайте добро и\nвзаймы давайте, ничего не ожидая обратно; и будет\nнаграда ваша велика, и будете сынами Всевышнего,\nпотому что Он благ к неблагодарным и злым.","36":"Будьте милосердны, как Отец ваш милосерден.","37":"Не судите, и не будете судимы. Не осуждайте, и\nне\nбудете\nосуждены.\nОтпускайте,\nи\nвам\nбудет\nотпущено.","38":"Давайте, и вам будет дано: мерою доброю,\nнагнетенною, утрясенною, переполненною отсыплют в\nполы ваши; ибо какою мерою вы мерите, отмерено\nбудет и вам.","39":"Сказал же и притчу им: разве может слепой\nвести слепого? Не оба ли упадут в яму?","40":"Ученик не выше учителя, но, научившись, всякий\nбудет, как учитель его.","41":"Что ты смотришь на соринку в глазу брата\nтвоего, а бревна в собственном глазу не замечаешь?","42":"Как можешь говорить брату твоему: «брат, дай, я\nвыну соринку, что в твоем глазу», не видя у себя в глазу\nбревна? Лицемер, вынь сперва бревно из твоего глаза, и\nтогда увидишь, как вынуть соринку, что в глазу брата\nтвоего.","43":"Нет дерева доброго, которое производило бы\nплохой\nплод,\nнет\nи\nдерева\nплохого,\nкоторое\nпроизводило бы добрый плод.","44":"Ибо всякое дерево познается по его плоду. Ведь\nс терния не собирают смокв, и с колючего кустарника\nвинограда не снимают.","45":"Добрый человек из доброго сокровища сердца\nизносит доброе, и злой из злого износит злое. Ибо от\nизбытка сердца говорят уста его.","46":"Что вы зовете Меня: «Господи, Господи!» и не\nделаете того, что Я говорю?","47":"Всякий, приходящий ко Мне и слушающий Мои\nслова и исполняющий их, – Я покажу вам, кому он\nподобен.","48":"Подобен он человеку, строящему дом, который\nраскопал землю и углубился и положил основание на\nскале. Когда же случилось наводнение, хлынула река\nна дом тот и не смогла поколебать его, потому что\nпостроен он был хорошо;","49":"а слышавший и не исполнивший подобен\nчеловеку, построившему дом на земле без основания. И\nхлынула на него река, и тотчас он развалился, и было\nпадение дома того великое."},"7":{"1":"Когда Он окончил все слова Свои к слушавшему\nнароду, Он вошел в Капернаум.","2":"И был при смерти больной раб некоего сотника,\nкоторому он был дорог.","3":"Услышав об Иисусе, он послал к нему старейшин\nИудейских, прося Его придти спасти раба его.","4":"И они, придя к Иисусу, просили Его усердно и\nговорили: он достоин, чтобы Ты сделал ему это:","5":"он любит народ наш, и сам построил нам синагогу.","6":"Иисус пошел с ними. И когда Он был уже недалеко\nот дома, сотник послал друзей сказать Ему: Господи, не\nутруждай Себя. Ибо не достоин я, чтобы Ты вошел ко\nмне под кров;","7":"поэтому я и себя самого не счел достойным\nпридти к Тебе, но только скажи, и будет исцелен отрок\nмой.","8":"Ведь и я человек подначальный, имеющий в своем\nподчинении воинов, и говорю одному: «пойди», и идет,\nи другому: «приходи», и приходит, и этому рабу моему:\n«сделай это», и делает.","9":"Услышал\nэто\nИисус\nи\nудивился\nему;\nи\nповернувшись к сопровождавшей Его толпе, сказал:\nговорю вам, что Я и в Израиле не нашел такой веры.","10":"И возвратившись в дом, посланные нашли раба\nздоровым.","11":"И\nбыло:\nнаправился\nОн\nпотом\nв\nгород,\nназываемый Наин, и шли с Ним ученики Его и много\nнарода.","12":"Когда же Он приблизился к городским воротам,\nто вот, выносили умершего, единственного сына у\nматери его, и она была вдова, и немало народа из\nгорода было с ней.","13":"И увидев ее, Господь сжалился над ней и сказал\nей: не плачь.","14":"И подойдя, Он прикоснулся к носилкам. Несшие\nостановились. И Он сказал: юноша, тебе говорю: встань!","15":"И сел мертвый и начал говорить; и Он отдал его\nматери его.","16":"И всех объял страх, и славили Бога, говоря:\nвеликий пророк восстал между нами, и Бог посетил\nнарод Свой.","17":"И это слово о Нем прошло по всей Иудее и по\nвсей округе.","18":"И возвестили Иоанну ученики его о всём этом.","19":"И призвав двоих из учеников своих, Иоанн послал\nих к Господу спросить: Ты ли Грядущий, или ожидать\nнам другого?","20":"И придя к Нему, эти люди сказали: Иоанн\nКреститель послал нас к Тебе спросить: «Ты ли\nГрядущий, или ожидать нам другого?","21":"В это самое время Он исцелил многих от\nболезней и недугов и духов злых, и многим слепым\nдаровал зрение.","22":"И он ответил им: пойдите, возвестите Иоанну,\nчто вы видели и слышали: слепые прозревают, хромые\nходят, прокаженные очищаются, и глухие слышат,\nмертвые восстают, нищим благовествуется,","23":"и блажен тот, кто не соблазнится из-за Меня.","24":"Когда же посланные Иоанна ушли, начал Он\nговорить народу об Иоанне: что смотреть ходили вы в\nпустыню? Не тростник же, ветром колеблемый?","25":"Но что же ходили вы смотреть? Человека,\nоблеченного в мягкие одеяния? Но в пышных нарядах и\nроскоши живущие находятся в царских дворцах.","26":"Так что же вышли вы смотреть? Пророка? Да,\nговорю вам, и больше, чем пророка.","27":"Это тот, о ком написано: «Вот, Я посылаю ангела\nМоего пред лицом Твоим, который приготовит путь Твой\nпред Тобою».","28":"Говорю вам: среди рожденных женами нет ни\nодного большего, чем Иоанн; но меньший в Царстве\nБожием больше его.","29":"И весь народ, услышав, и мытари признали\nправым Бога, крестившись крещением Иоанновым.","30":"Фарисеи же и законники отвергли волю Божию о\nсебе, не крестившись у него.","31":"Итак, кому уподоблю людей рода этого, и кому\nони подобны?","32":"Они подобны детям, которые сидят на площади и\nобращаются друг к другу, говоря: «Мы играли вам на\nсвирели, и вы не плясали, мы пели вам печальные\nпесни, и вы не плакали».","33":"Ибо пришел Иоанн Креститель: не ест хлеба и не\nпьет вина, и вы говорите: «в нем бес».","34":"Пришел Сын Человеческий: ест и пьет, и вы\nговорите: «вот человек, любящий есть и пить вино, друг\nмытарей и грешников».","35":"И оправданием премудрости были все дети ее.","36":"И просил Его некто из фарисеев вкусить с ним. И\nвойдя в дом фарисея, Он возлег.","37":"И вот, женщина, которая была известна в городе\nкак грешница, узнав, что Он возлежит в доме фарисея,\nпринесла алебастровый сосуд с миром","38":"и, став сзади у ног Его, начала, плача, обливать\nноги Его слезами и волосами головы своей отирала и\nцеловала ноги Его и мазала миром.","39":"Увидев это, фарисей, пригласивший Его, сказал\nсамому себе: Этот, если бы Он был пророк, знал бы, кто\nи какая женщина прикасается к Нему, потому что она\nгрешница.","40":"И Иисус ему ответил: Симон, Я имею нечто\nсказать тебе. Он говорит: скажи, Учитель.","41":"У некоего заимодавца было два должника: один\nдолжен был пятьсот динариев, а другой пятьдесят.","42":"Так как им нечем было заплатить, он простил\nобоим. Кто же из них больше возлюбит его?","43":"Симон ответил: полагаю, что тот, кому он больше\nпростил. Он же сказал ему: ты правильно рассудил.","44":"И обратившись к женщине, сказал Симону:\nвидишь ли ты эту женщину? Я вошел к тебе в дом: ты\nводы Мне на ноги не дал, она же слезами облила Мне\nноги и отерла волосами своими;","45":"ты целования Мне не дал, она же, с тех пор, как\nЯ вошел, не переставала целовать Мне ноги;","46":"ты елеем головы Моей не помазал, она же миром\nпомазала ноги Мои.","47":"Поэтому говорю тебе: прощены грехи ее многие\nза то, что она возлюбила много. А кому мало прощается,\nтот мало любит.","48":"И Он сказал ей: прощены твои грехи.","49":"И начали возлежавшие с ним говорить самим\nсебе: кто это, что и грехи прощает?","50":"Он же сказал женщине: вера твоя спасла тебя,\nиди с миром."},"8":{"1":"И было: ходил Он потом по городам и селениям,\nпроповедуя\nи\nблаговествуя\nЦарство\nБожие,\nи\nДвенадцать с Ним,","2":"и женщины некие, которые получили исцеление\nот\nзлых\nдухов\nи\nболезней:\nМария,\nназываемая\nМагдалиной, из которой вышло семь бесов,","3":"и Иоанна, жена Хузы, состоящего при Ироде, и\nСусанна, и другие многие, служившие им своим\nимением.","4":"Когда же начало собираться много народа, и люди\nиз всех городов приходили к Нему, Он сказал в притче:","5":"вышел сеятель сеять семя свое, и когда сеял, иное\nсемя упало при дороге и было затоптано, и птицы\nнебесные поклевали его.","6":"Иное упало на скалу и, взойдя, засохло, потому\nчто не имело влаги.","7":"А иное упало между тернием, но взошло с ним и\nтерние и заглушило его.","8":"И иное упало на землю добрую и взошло и\nпроизвело плод сторичный. Говоря это, Он возглашал:\nимеющий уши слышать, да слышит.","9":"И спрашивали Его ученики Его: что могла бы\nзначить притча эта?","10":"Он же сказал: вам дано познать тайны Царства\nБожия, а прочим в притчах, чтобы они видя не видели и\nслыша не уразумели.","11":"Вот, что значит эта притча: семя есть слово\nБожие.","12":"Те, что при дороге, – это услышавшие; затем\nприходит диавол и уносит слово из сердца их, чтобы\nони, уверовав, не были спасены.","13":"Те же, что на скале, – это те, которые, услышав, с\nрадостью приемлют слово, но не имеют корня; они\nкороткое время верят, и во время искушения отступают.","14":"А упавшее в терние, – это услышавшие, но на\nпутях жизни подавляют их заботы и богатство и\nнаслаждения житейские: и их плоды не дозревают.","15":"А то, что на доброй земле, – это те, которые,\nуслышав слово, держат его в сердце добром и благом и\nдают плод в терпении.","16":"Никто, зажегши светильник, не покрывает его\nсосудом или не ставит под кровать, а ставит на\nподсвечник, чтобы входящие видели свет.","17":"Ибо нет скрытого, что не стало бы явным, ни\nсокровенного, что не было бы узнано и не вышло бы\nнаружу.","18":"Итак, смотрите, как вы слушаете. Ибо кто имеет,\nтому дано будет, и кто не имеет, у того взято будет и\nто, что ему кажется, что он имеет.","19":"И пришли к Нему Матерь и братья Его, и не могли\nдобраться до Него из-за толпы,","20":"и дано было знать Ему: Матерь Твоя и братья\nТвои пришли и стоят снаружи, желая видеть Тебя.","21":"Он же ответил им: матерь Моя и братья Мои – это\nслушающие слово Божие и исполняющие его.","22":"Было однажды: Он Сам вошел в лодку и ученики\nЕго; и сказал Он им: переправимся на ту сторону озера.\nИ они отплыли.","23":"А во время плавания их Он заснул. И налетел\nвихрь на озеро, и стало их заливать, и были они в\nопасности.","24":"Подойдя же, разбудили Его, говоря: Наставник!\nНаставник! Погибаем. Он же, пробудившись, возбранил\nветру и взбушевавшейся воде, и они улеглись, и\nнастала тишина.","25":"И Он сказал им: где вера ваша? А они в страхе и\nудивлении говорили друг другу: Кто же Он, что и\nветрам повелевает и воде, и они повинуются Ему?","26":"И они приплыли в страну Герасинскую, которая\nнапротив Галилеи.","27":"Когда же Он вышел на землю, встретил Его\nнекий\nчеловек\nиз\nгорода,\nодержимый\nбесами;\nи\nдовольно давно он не носил одежды и жил не в доме, а\nв могильных пещерах.","28":"Увидев же Иисуса, он вскричал, припал к Его\nногам и громким голосом сказал: что Тебе до меня,\nИисус, Сын Бога Всевышнего? Молю Тебя, не мучь меня.","29":"Ибо повелевал Он духу нечистому выйти из этого\nчеловека: ибо уже в течение многих лет схватывал он\nего; и связывали его цепями и кандалами и стерегли; но\nон разрывал узы, и бес гнал его в пустыню.","30":"Спросил же его Иисус: как тебе имя? Он же\nсказал: легион, так как много бесов вошло в него.","31":"И они просили Его, чтобы не велел им идти в\nбездну.","32":"Паслось же там на горе большое стадо свиней. И\nони попросили Его позволить им в них и войти. И\nпозволил им.","33":"И выйдя из человека, бесы вошли в свиней, и\nринулось стадо с крутизны в озеро и утонуло.","34":"Пастухи же, увидев происшедшее, побежали и\nобъявили в городе и в деревнях.","35":"И вышли люди посмотреть, что случилось, и\nпришли к Иисусу и нашли человека, из которого вышли\nбесы, сидящим у ног Иисуса, одетым и в здравом уме, и\nустрашились.","36":"И сообщили им видевшие, как спасен был\nбесновавшийся.","37":"И попросил Его весь народ страны Герасинской\nуйти от них, так как они объяты были великим страхом.\nОн же, войдя в лодку, возвратился.","38":"И человек, из которого вышли бесы, просил Его\nбыть с Ним. Но Он отпустил его и сказал:","39":"возвращайся в дом твой и говори, что сделал\nтебе Бог. И он пошел, проповедуя по всему городу, что\nсделал ему Иисус.","40":"А при возвращении Иисуса принял Его народ, ибо\nвсе ждали Его.","41":"И вот, пришел человек по имени Иаир. Был он\nначальник синагоги. И пав к ногам Иисуса, просил Его\nвойти к нему в дом,","42":"потому что была у него единственная дочь лет\nдвенадцати, и она умирала. И когда Он шел, народ\nтеснил Его.","43":"И\nженщина,\nстрадавшая\nкровотечением\nдвенадцать лет, которая издержала на врачей все\nимущество, и никто не мог ее вылечить, –","44":"подойдя сзади, прикоснулась к краю одежды Его,\nи тотчас остановилась у нее кровь.","45":"И сказал Иисус: кто прикоснулся ко Мне? Когда\nже все отрекались, сказал Петр и бывшие с Ним:\nНаставник, народ окружает Тебя и теснит.","46":"Иисус же сказал: прикоснулся ко Мне некто, ибо\nя почувствовал силу, исшедшую из Меня.","47":"Женщина же, увидев, что не утаилась, подошла\nдрожа и, припав к Его ногам, объявила перед всем\nнародом, по какой причине коснулась Его, и как тотчас\nбыла исцелена.","48":"Он же сказал ей: дочь Моя, вера твоя спасла\nтебя; иди с миром.","49":"Пока еще Он говорил, приходит некто от\nначальника синагоги и говорит: умерла дочь твоя, не\nутруждай больше Учителя.","50":"Иисус же, услышав, ответил ему: не бойся,\nтолько поверь, и будет спасена.","51":"И придя в дом, не позволил войти вместе с Ним\nникому, кроме Петра, Иоанна и Иакова и отца ребенка и\nматери.","52":"Плакали же все и били себя в грудь по ней, но Он\nсказал: не плачьте, она не умерла, но спит.","53":"И смеялись над Ним, зная, что она умерла.","54":"А Он, взяв ее за руку, возгласил: дитя, встань!","55":"И возвратился дух ее, и тотчас она встала, и Он\nвелел дать ей есть.","56":"И изумились родители ее. Он же повелел им\nникому не говорить о происшедшем."},"9":{"1":"Созвав же Двенадцать, дал им силу и власть над\nвсеми бесами и лечить болезни,","2":"и послал их проповедывать Царство Божие и\nисцелять больных.","3":"И сказал им: ничего не берите в дорогу: ни посоха,\nни сумы, ни хлеба, ни денег, и не имейте по две\nрубашки.","4":"И в какой бы вы дом ни вошли, там оставайтесь, и\nоттуда снова выходите в путь.","5":"А где не будут принимать вас, – выходя в путь из\nгорода\nтого,\nотряхните\nпыль\nс\nног\nваших\nво\nсвидетельство на них.","6":"И выходили они в путь, и проходили по селениям,\nблаговествуя и исцеляя повсюду.","7":"Услышал же Ирод тетрарх о всём происходящем и\nнедоумевал, так как некоторые говорили, что Иоанн\nвосстал из мертвых,","8":"а некоторые, что Илия явился, другие же, что\nнекий из древних пророков воскрес.","9":"И сказал Ирод: Иоанна я обезглавил. Кто же Этот,\nо Ком я слышу такое? И искал увидеть Его.","10":"И апостолы, возвратившись, рассказали Ему, что\nони сделали. И взяв их с Собою, Он удалился отдельно\nот\nдругих\nв\nнаправлении\nгорода,\nназываемого\nВифсаидою.","11":"Но народ, узнав, последовал за Ним, и Он, приняв\nих, говорил с ними о Царстве Божием и нуждавшихся во\nврачевании исцелял.","12":"День начал склоняться к вечеру; подойдя же,\nДвенадцать сказали Ему: отпусти народ, чтобы они\nотправились в окрестные селения и деревни и нашли\nсебе кров и пропитание, потому что мы здесь в\nпустынном месте.","13":"Но Он сказал им: вы им дайте есть. Они же\nсказали: у нас только пять хлебов и две рыбы, если,\nконечно, мы не пойдем купить пищи для всего этого\nнарода.","14":"Было, ведь, их около пяти тысяч мужчин. Но Он\nсказал ученикам Своим: расположите их группами\nчеловек по пятидесяти.","15":"И сделали так, и расположили всех.","16":"Взяв же эти пять хлебов и эти две рыбы, поднял\nОн глаза к небу, благословил их и преломил и давал\nученикам разносить народу;","17":"и ели и насытились все. И оставшихся у них\nкусков собрано было двенадцать коробов.","18":"И было: когда Он молился в уединении, ученики\nбыли с Ним, и Он спросил их: за кого Меня почитают в\nнароде?","19":"Они ответили: за Иоанна Крестителя, другие же\nза Илию, а иные, что некий пророк из древних воскрес.","20":"И сказал им: а вы за кого Меня почитаете? Петр\nответил: за Христа Божия.","21":"Он же строго повелел им никому не говорить об\nэтом,","22":"сказав, что надлежит Сыну Человеческому много\nпострадать\nи\nбыть\nотвергнутым\nстарейшинами\nи\nпервосвященниками и книжниками, и быть убитым, и в\nтретий день восстать.","23":"Говорил же Он всем: если кто хочет за Мною\nидти, да отречется от самого себя и да берет крест свой\nвсякий день, и следует за Мною.","24":"Ибо, кто хочет душу свою спасти, тот погубит ее;\nкто же погубит душу свою ради Меня, тот и спасет ее.","25":"Ибо что выгадает человек, приобретя весь мир, а\nсебя самого погубив, или повредив себе?","26":"Ибо, кто постыдится Меня и Моих слов, того Сын\nЧеловеческий постыдится, когда придет во славе Своей\nи Отца и святых ангелов.","27":"Говорю же вам истинно: есть некоторые из\nстоящих здесь, которые не вкусят смерти, доколе не\nувидят Царства Божия.","28":"И было после этих слов дней через восемь:\nИисус, взяв Петра, Иоанна и Иакова, поднялся на гору\nпомолиться.","29":"И когда Он молился, сделался вид лица Его\nиным, и одеяние Его белым, сверкающим,","30":"И вот, два мужа беседовали с Ним. Были они\nМоисей и Илия.","31":"Явившись во славе, они говорили о Его исходе,\nкоторый предстояло совершить Ему в Иерусалиме.","32":"Петр же и бывшие с Ним отягчены были сном, но,\nочнувшись, увидели славу Его и двух мужей, стоящих с\nНим.","33":"И было: когда они расставались с Ним, сказал\nПетр Иисусу: Наставник, хорошо нам здесь быть,\nсделаем три шатра: один Тебе, и один Моисею, и один\nИлии, – не зная, что он говорит.","34":"И пока он это говорил, появилось облако и\nосенило их; и устрашились они, когда вошли в облако.","35":"И голос раздался из облака: Это Сын Мой\nИзбранный, Его слушайте.","36":"И когда голос прозвучал, оказался Иисус один. И\nони сохранили молчание, и никому не возвестили в те\nдни ничего из того, что видели.","37":"И было: на следующий день, когда спустились\nони с горы, встретила Его большая толпа.","38":"И вот, человек из толпы закричал: Учитель,\nпрошу Тебя взглянуть на сына моего, потому что он\nодин у меня.","39":"И\nвот,\nдух\nсхватывает\nего,\nи\nвнезапно\nвскрикивает, и сводит его судорогой с пеной и, изнуряя\nего, насилу отходит от него.","40":"И я просил учеников Твоих изгнать его, и они не\nсмогли.","41":"Иисус\nже\nответил:\nо\nрод\nневерный\nи\nразвращенный, доколе буду с вами и буду выносить\nвас? Приведи сюда сына твоего.","42":"И пока тот еще подходил, бес бросил его на\nземлю и свел сильной судорогой. Но Иисус возбранил\nдуху нечистому и исцелил отрока и отдал его отцу его.","43":"И изумлялись все величию Божию. Когда же все\nдивились всему тому, что делал Иисус, Он сказал\nученикам Своим:","44":"вложите вы себе в уши слова эти: Сын\nЧеловеческий будет предан в руки человеческие.","45":"Они же не понимали речи этой, и была она\nскрыта от них для того, чтобы они не постигли ее. И\nбоялись они спросить Его об этой речи.","46":"И возникла у них мысль, кто из них больше.","47":"Иисус же, зная мысль сердца их, взял дитя,\nпоставил его около Себя","48":"и сказал им: кто примет это дитя во имя Мое,\nМеня принимает, и кто Меня примет, принимает\nПославшего Меня. Ибо кто меньше между всеми вами, –\nтот и велик.","49":"Иоанн\nже\nсказал:\nНаставник,\nмы\nвидели\nчеловека,\nименем\nТвоим\nизгоняющего\nбесов,\nи\nпрепятствовали ему, потому что он не следует за Тобою\nвместе с нами.","50":"И сказал ему Иисус: не препятствуйте, ибо кто не\nпротив вас, тот за вас.","51":"И было: когда подходили к концу дни перед Его\nвознесением, Он решил идти в Иерусалим,","52":"и послал вестников пред лицом Своим. И\nотправившись, они вошли в селение Самарянское с тем,\nчтобы приготовить для Него.","53":"И не приняли Его, так как путь Его был в\nИерусалим.","54":"Увидев же это, ученики Иаков и Иоанн сказали:\nГосподи, хочешь ли, мы скажем, чтобы огонь сошел с\nнеба и истребил их.","55":"Но обернувшись, Он возбранил им.","56":"И отправились в другое селение.","57":"И когда они шли, кто-то в пути сказал Ему: я буду\nследовать за Тобою, куда бы Ты ни шел.","58":"И сказал ему Иисус: у лисиц есть норы, и у птиц\nнебесных гнёзда, Сыну же Человеческому некуда\nголову приклонить.","59":"И сказал другому: следуй за Мною. Он же сказал:\nГосподи, позволь мне сперва пойти похоронить отца\nмоего.","60":"Но Он сказал ему: предоставь мертвым хоронить\nсвоих мертвых. Ты же иди возвещать Царство Божие.","61":"Сказал и другой: я последую за Тобою, Господи,\nно сперва позволь мне проститься с домашними моими.","62":"Иисус же сказал ему: никто, возложивший руку\nсвою на плуг и озирающийся назад, не пригоден для\nЦарства Божия."},"10":{"1":"После этого поставил Господь и других семьдесят\nи послал их по два пред лицом Своим, в каждый город и\nместо, куда предстояло Ему Самому идти,","2":"и говорил им: жатвы много, а работников мало;\nпоэтому\nмолите\nГосподина\nжатвы,\nчтобы\nвыслал\nработников на жатву Свою.","3":"Идите! Вот, посылаю вас, как ягнят посреди\nволков.","4":"Не носите с собой ни мешка, ни сумы, ни обуви, и\nникого в пути не приветствуйте.","5":"И в какой бы вы дом ни вошли, прежде всего\nговорите: «мир дому сему».","6":"И если будет там сын мира, то низойдет на него\nмир ваш; если же нет, то на вас возвратится.","7":"И в этом доме оставайтесь, ешьте и пейте, что у\nних есть: ибо достоин работник награды своей. Не\nпереходите из дома в дом.","8":"И в какой бы вы город ни входили, – если примут\nвас, ешьте предлагаемое вам,","9":"и исцеляйте находящихся в нем больных и\nговорите им: «близко к вам Царство Божие».","10":"И в какой бы вы город ни вошли, – если не\nпримут вас, то, выйдя на улицы его, скажите:","11":"«и пыль, прилипшую к нашим ногам от города\nвашего, мы отрясаем вам. Знайте однако то, что близко\nЦарство Божие».","12":"Говорю вам, что Содому в день тот будет легче,\nчем городу тому.","13":"Горе тебе, Хоразин! Горе тебе, Вифсаида! Ибо,\nесли бы в Тире и Сидоне были совершены чудеса,\nсовершившиеся в вас, то давно бы они, сидя в рубище и\nпепле, покаялись.","14":"Но Тиру и Сидону легче будет на суде, чем вам.","15":"И ты, Капернаум, до неба ли ты будешь\nвознесён? До ада ты будешь низвергнут.","16":"Слушающий вас Меня слушает, и отвергающий\nвас Меня отвергает, а Меня отвергающий отвергает\nПославшего Меня.","17":"Возвратились же семьдесят с радостью и\nговорили: Господи, и бесы покоряются нам во имя Твое.","18":"Он же сказал им: Я видел сатану как молнию с\nнеба упавшего.","19":"Вот, Я дал вам власть наступать на змей и\nскорпионов и – над всею силою врага; и ничто не\nповредит вам.","20":"Но тому не радуйтесь, что духи вам покоряются,\nа радуйтесь, что имена ваши вписаны на небесах.","21":"В этот час Он возликовал Духом Святым и сказал:\nславлю Тебя, Отче, Господи неба и земли, что Ты сокрыл\nэто от мудрых и разумных и открыл это младенцам. Да,\nОтче, ибо так было благоугодно Тебе.","22":"Всё Мне предано Отцом Моим; и никто не знает,\nкто есть Сын, кроме Отца; и кто есть Отец – никто,\nкроме Сына, и кому хочет Сын открыть.","23":"И обратившись к ученикам отдельно от других,\nсказал: блаженны очи, видящие то, что вы видите.","24":"Ибо говорю вам: многие пророки и цари хотели\nувидеть то, что видите вы, и не увидели, и услышать то,\nчто вы слышите, и не услышали.","25":"И вот встал некий законник, искушая Его, и\nсказал:\nУчитель,\nчто\nя\nдолжен\nсделать,\nчтобы\nнаследовать жизнь вечную?","26":"Он же сказал ему: в Законе что написано? Как\nчитаешь?","27":"И он ответил: «Возлюби Господа Бога твоего\nвсем сердцем твоим и всею душою твоею и всею\nкрепостью твоею и всем разумом твоим», и: «ближнего\nтвоего, как самого себя».","28":"И Он сказал ему: ты правильно ответил: так\nпоступай и будешь жить.","29":"Но он, желая оправдать себя, сказал Иисусу: а\nкто мой ближний?","30":"Иисус\nтотчас\nже\nответил:\nчеловек\nнекий\nспускался\nиз\nИерусалима\nв\nИерихон\nи\nпопался\nразбойникам; они его раздели и изранили, и ушли,\nоставив полумертвым.","31":"Случайно священник некий спускался дорогою\nтой и, увидев его, прошел мимо.","32":"Также и левит, придя на это место и увидев его,\nпрошел мимо.","33":"Самарянин же некий, находившийся в пути,\nнатолкнулся на него и увидев сжалился","34":"и подойдя перевязал раны его, возливая масло и\nвино; и посадив его на своего осла, привез его в\nгостиницу и позаботился о нем;","35":"и на другой день, вынув два динария, дал\nхозяину гостиницы и сказал: «позаботься о нем, и что\nперерасходуешь, я на обратном пути заплачу тебе».","36":"Кто из этих троих, думается тебе, оказался\nближним попавшему в руки разбойников?","37":"Он сказал: сотворивший ему милость. Сказал же\nему Иисус: иди, и ты поступай так же.","38":"И во время пути их вошел Он в одно селение. И\nженщина некая, по имени Марфа, приняла Его в дом\nсвой.","39":"И у нее была сестра, называвшаяся Марией,\nкоторая и села у ног Господа и слушала слово Его.","40":"Марфа же вся была поглощена услужением. Она\nподошла и сказала: Господи, Тебе дела нет, что сестра\nмоя одну меня оставила служить? Скажи ей, чтобы она\nмне помогла.","41":"И\nответил\nей\nГосподь:\nМарфа,\nМарфа,\nзаботишься ты и беспокоишься о многом,","42":"а одно только нужно: Мария же благую долю\nизбрала, которая не отнимется у нее."},"11":{"1":"И было; в то время, как Он в некоем месте\nмолился, кто-то из учеников Его сказал Ему, когда Он\nперестал: Господи, научи нас молиться, как и Иоанн\nнаучил учеников своих.","2":"Он же сказал им: когда молитесь, говорите: Отче!\nДа святится имя Твое. Да придет Царство Твое.","3":"Хлеб наш насущный подавай нам каждый день.","4":"И прости нам грехи наши, ибо и мы сами прощаем\nвсякому, кто должен нам. И не введи нас во искушение.","5":"И сказал им: у кого из вас будет друг, и придет он\nк нему в полночь и скажет ему: «друг, дай мне в долг\nтри хлеба,","6":"потому что друг мой пришел ко мне с пути, и мне\nнечего предложить ему»;","7":"и тот изнутри ему ответит: «не беспокой меня:\nдверь уже заперта, и дети мои со мною на постели; не\nмогу встать и дать тебе», –","8":"говорю вам: если он и не встанет и не даст ему по\nдружбе с ним, то по неотступности его поднимется и\nдаст ему всё, что ему нужно.","9":"И Я говорю вам: просите, и дано будет вам; ищите\nи найдете; стучитесь, и отворят вам.","10":"Ибо всякий просящий получает, и ищущий\nнаходит, и стучащемуся отворят.","11":"Какой из вас отец, если сын попросит хлеба,\nподаст ему камень? Или рыбы, – и он, вместо рыбы,\nподаст ему змею?","12":"Или, может быть, попросит яйцо? Неужели он\nподаст ему скорпиона?","13":"Итак, если вы, будучи злы, умеете давать дары\nблагие детям вашим, тем более Отец Небесный даст\nДуха Святого просящим у Него.","14":"И изгонял Он беса; и бес был немой. И было:\nкогда бес вышел, немой заговорил. И изумился народ,","15":"а некоторые из них сказали: Он изгоняет бесов\nВеельзевулом, князем бесовским.","16":"А другие, искушая, требовали от Него знамения с\nнеба.","17":"Он же, зная их мысли, сказал им: всякое царство,\nразделенное\nвнутреннею\nвраждой,\nобращается\nв\nпустыню, и дом на дом падает.","18":"Если же и сатана в самом себе разделился, как\nустоит\nцарство\nего?\nВедь\nвы\nговорите,\nчто\nя\nВеельзевулом изгоняю бесов.","19":"Если же Я Веельзевулом изгоняю бесов, то\nсыновья ваши кем изгоняют? Поэтому они будут вам\nсудьями.","20":"Если же Я перстом Божиим изгоняю бесов, –\nзначит, достигло до вас Царство Божие.","21":"Когда сильный с оружием охраняет свой дворец,\nимущество его в безопасности.","22":"Когда же сильнейший его нападет и победит его,\nтогда берет он вооружение его, на которое тот\nполагался, и делит доставшуюся от него добычу.","23":"Кто не со Мною, тот против Меня, и кто не\nсобирает со Мною, тот расточает.","24":"Когда нечистый дух выйдет из человека, то\nбродит по безводным местам, ища покоя, и не находя,\nговорит: «возвращусь в дом мой, откуда вышел»;","25":"и придя, находит его выметенным и убранным;","26":"тогда он идет и берет других духов, злейших\nсебя, числом семь, и войдя, они поселяются там, и\nстановится для человека того последнее хуже первого.","27":"И было: когда Он говорил это, некая женщина,\nвозвысив голос из толпы, сказала: блаженно чрево,\nносившее Тебя, и сосцы, вскормившие Тебя.","28":"А Он сказал: еще блаженнее слышащие слово\nБожие и соблюдающие его.","29":"А когда стало скопляться всё больше народа,\nначал Он говорить: род этот – род лукавый. Он ищет\nзнамения, и не будет дано ему знамения, кроме\nзнамения Ионы;","30":"ибо\nкак\nоказался\nИона\nзнамением\nдля\nНиневитян, так будет и Сын Человеческий для этого\nрода.","31":"Царица Юга будет воздвигнута во время суда\nвместе с людьми рода этого, и осудит их, потому что\nона пришла от пределов земли послушать мудрость\nСоломонову, и вот, то, что здесь, больше Соломона.","32":"Люди Ниневийские восстанут во время суда\nвместе с родом этим, и осудят его, потому что они\nпокаялись от проповеди Ионы, – и вот, то, что здесь,\nбольше Ионы.","33":"Никто, зажегши светильник, не ставит его ни в\nдальнем углу, ни под сосуд, но на подсвечник, чтобы\nвходящие видели свет.","34":"Светильник тела есть глаз твой. Когда глаз твой\nчист, то и всё тело твое светло: а когда он плох, то и всё\nтело твое темно.","35":"Итак, смотри: свет, который в тебе, не есть ли\nтьма?","36":"Если же тело твое всё светло, и нет в нем ни\nодной темной части, то будет оно всё светло, как\nбывает, когда светильник блистанием освещает тебя.","37":"И когда Он это сказал, просит Его один фарисей\nпоесть у него. Он вошел и возлег.","38":"Фарисей же удивился, увидев, что Он прежде\nвсего не умылся перед едой.","39":"Но Господь сказал ему: ныне вы, фарисеи,\nочищаете снаружи чашу и блюдо, а что внутри у вас,\nполно хищения и лукавства.","40":"Безумные! Кто сотворил внешнее, не Он ли\nсотворил и внутреннее?","41":"Лишь бы вы дали, как милостыню, то, что внутри,\nи вот, всё у вас чисто.","42":"Но горе вам, фарисеям, что даете десятину с\nмяты и руты и всяких овощей и нерадите о правосудии\nи о любви Божией: это надлежало исполнить и того не\nопустить.","43":"Горе\nвам,\nфарисеям,\nчто\nлюбите\nпредседательство\nв\nсинагогах\nи\nприветствия\nна\nплощадях.","44":"Горе вам, что вы – как могилы, которых не видно,\nи люди ходят по ним и не знают.","45":"И отозвавшись, кто-то из законников говорит\nЕму: Учитель, говоря это, Ты и нас оскорбляешь.","46":"Но Он сказал: и вам, законникам, горе, что\nвозлагаете на людей ноши неудобоносимые, а сами ни\nединым пальцем не дотрагиваетесь до этих нош.","47":"Горе вам, что строите гробницы пророков, – а\nотцы ваши убили их;","48":"значит, вы свидетели и соглашаетесь с делами\nотцов ваших, потому что они их убили, а вы строите.","49":"Поэтому и премудрость Божия сказала: пошлю к\nним пророков и апостолов, и некоторых из них убьют и\nбудут гнать,","50":"чтобы\nкровь\nвсех\nпророков,\nпролитая\nот\nоснования мира, была взыскана с этого рода:","51":"от крови Авеля до крови Захарии, погибшего\nмежду жертвенником и святилищем. Да, говорю вам:\nона будет взыскана с рода этого.","52":"Горе вам, законникам, что вы взяли ключ знания:\nсами не вошли и входящим воспрепятствовали.","53":"И когда Он вышел оттуда, начали книжники и\nфарисеи сильно наступать на Него и выспрашивать Его\nеще о многом,","54":"ставя Ему западни с целью уловить что-нибудь\nиз уст Его."},"12":{"1":"Тем временем, когда собрались тьмы народа, так\nчто давили друг друга, Он начал говорить сперва Своим\nученикам: берегите себя от закваски, то есть от\nлицемерия, фарисеев.","2":"Нет ничего сокровенного, что не открылось бы, и\nтайного, чего не узнали бы.","3":"Поэтому, что вы сказали в темноте, то будет\nуслышано при свете, и что вы промолвили на ухо внутри\nдома, будет проповедано на кровлях.","4":"Говорю же вам, друзьям Моим: не бойтесь\nубивающих тело, и затем неспособных ничего больше\nсделать.","5":"Но укажу вам, кого бояться. Бойтесь того, кто по\nубиении имеет власть ввергнуть в геенну. Да, говорю\nвам: его бойтесь.","6":"Не пять ли воробьев продаются за два ассария? И\nни один из них не забыт у Бога.","7":"А у вас на голове и волосы все сосчитаны. Итак, не\nбойтесь: вы лучше многих воробьев.","8":"Говорю же вам: всякого, кто исповедает Меня\nпред людьми, – и Сын Человеческий исповедает его\nпред ангелами Божиими.","9":"А отвергнувший Меня пред людьми, будет\nотвергнут пред ангелами Божиими.","10":"И\nвсякий,\nкто\nскажет\nслово\nна\nСына\nЧеловеческого, – будет прощено ему. Но произнесшему\nхулу на Святого Духа не будет прощено.","11":"Когда же будут приводить вас в синагоги и к\nначальствам и властям, не заботьтесь, как или что\nответить вам в свою защиту, или что сказать.","12":"Ибо Святой Дух научит вас в этот самый час, что\nнадо сказать,","13":"И сказал Ему кто-то из толпы: Учитель, скажи\nбрату моему, чтобы он разделил со мной наследство.","14":"Он же сказал ему: человек, кто поставил Меня\nсудить или делить вас?","15":"И Он сказал им: смотрите, храните себя от\nвсякого любостяжания, потому что и при изобилии\nжизнь человека не зависит от его имущества.","16":"И сказал им притчу: у одного богатого человека\nхорошо уродила земля,","17":"и он рассуждал сам с собой: «что мне делать, раз\nнекуда мне собрать плодов моих?»","18":"И сказал: «вот, что сделаю: снесу мои житницы и\nпострою большие, и соберу туда всю пшеницу и всё\nдобро мое,","19":"и скажу душе моей: душа, много добра лежит у\nтебя на многие годы: покойся, ешь, пей, веселись».","20":"И сказал ему Бог: «безумный, в эту ночь душу\nтвою потребуют у тебя, а то, что ты заготовил, кому\nдостанется?»","21":"Таков собирающий сокровища себе, а не в Бога\nбогатеющий.","22":"И Он сказал ученикам Своим: поэтому говорю\nвам: не заботьтесь для души, что вам есть, ни для тела,\nво что вам одеться.","23":"Ибо душа больше пищи, и тело одежды.","24":"Подумайте о воронах: они не сеют, не жнут, нет\nу них ни хранилища, ни житницы, и Бог питает их.\nНасколько же вы лучше птиц.","25":"И кто из вас, заботясь, может к сроку жизни\nсвоей прибавить малую меру?","26":"Если же вы и самого малого не можете, что\nзаботитесь об остальном?","27":"Подумайте о лилиях, как они растут: не трудятся\nи не прядут. Но говорю вам, что и Соломон во всей\nславе своей никогда не одевался, как любая из них.","28":"Если же в поле траву, которая есть сегодня, а\nзавтра будет брошена в печь, Бог так наряжает, то\nнасколько больше вас, маловеры!","29":"И вы не ищите, что вам есть, и что вам пить, и не\nтревожьтесь.","30":"Ибо всего этого ищут народы мира. Ваш же Отец\nзнает, что вы нуждаетесь в этом.","31":"Но ищите Царства Его, и это приложится вам.","32":"Не бойся, малое стадо, ибо благоволил Отец ваш\nдать вам Царство.","33":"Продайте, что у вас есть, и отдайте как\nмилостыню, сделайте себе вместилища неветшающие,\nсокровище неисчерпаемое на небесах, куда вор не\nприближается, и где моль не разрушает.","34":"Ибо где сокровище ваше, там и сердце ваше\nбудет.","35":"Да\nбудут\nчресла\nваши\nпрепоясанными\nи\nсветильники горящими,","36":"и вы сами – подобными людям, ожидающим\nгосподина своего: когда же он вернется с брачного\nпира? Чтобы, как только он придет и постучится, тотчас\nотворить ему.","37":"Блаженны рабы те, которых, придя, господин\nнайдет\nбодрствующими.\nИстинно\nговорю\nвам:\nпрепояшется он и заставит их возлечь и, подойдя, будет\nслужить им.","38":"Если и во вторую, если и в третью стражу придет\nи найдет всё так, блаженны они.","39":"Но вот, что вы знаете: если бы ведал хозяин\nдома, в какой час придет вор, – не допустил бы он\nподкопать дома своего.","40":"И вы готовьтесь, ибо в час, в какой не думаете,\nпридет Сын Человеческий.","41":"Сказал же Петр: Господи, нам говоришь Ты эту\nпритчу, или и всем?","42":"И сказал Господь: кто верный домоправитель,\nразумный, которого поставит господин над слугами\nсвоими, чтобы давать в свое время меру хлеба?","43":"Блажен раб тот, которого господин его, придя,\nнайдет поступающим так.","44":"Поистине говорю вам: над всем имением своим\nпоставит его.","45":"Если же скажет раб тот в сердце своем: «медлит\nгосподин мой придти», и начнет бить слуг и служанок, и\nесть и пить и напиваться, –","46":"придет господин раба того в день, в который он\nне ожидает, и в час, которого не знает, и рассечет его\nнадвое и подвергнет его одной участи с неверными.","47":"И раб тот – узнавший волю господина своего и не\nприготовивший или не сделавший по воле его – бит\nбудет много.","48":"А не узнавший, но сделавший достойное побоев,\n– бит будет мало. Всякому же, кому дано много, с него\nмного будет взыскано, и кому вверено много, больше\nспросят с него.","49":"Огонь пришел Я принести на землю, и как хочу Я,\nчтобы он уже возгорелся.","50":"Крещением должен Я креститься, и как Я\nтомлюсь, доколе это не совершится.","51":"Думаете ли вы, что Я пришел дать мир на земле?\nНет, говорю вам, но разделение.","52":"Ибо\nотныне\nпятеро\nв\nодном\nдоме\nбудут\nразделены: трое против двух, и двое против трех.","53":"Разделятся: отец против сына, и сын против\nотца; мать против дочери, и дочь против матери;\nсвекровь против невестки своей, и невестка против\nсвекрови.","54":"Говорил же и народу: когда видите, что облако\nподнимается на западе, вы тотчас говорите: «дождь\nбудет», и бывает так.","55":"И когда видите, что южный ветер дует, вы\nговорите: «зной будет», и бывает.","56":"Лицемеры, лицо земли и неба распознавать вы\nумеете, как же времени этого не распознаёте?","57":"Почему же вы и по самим себе не судите, что\nсправедливо?","58":"Ибо, когда ты идешь с противником твоим к\nначальству, – то дорогой постарайся освободиться от\nнего, чтобы он не повлек тебя к судье; а судья отдаст\nтебя стражу, а страж бросит тебя в тюрьму.","59":"Говорю тебе, не выйдешь ты оттуда, пока не\nотдашь и последнего гроша."},"13":{"1":"И в это самое время пришли некоторые и\nсообщили Ему о Галилеянах, кровь которых Пилат\nсмешал с их жертвами.","2":"И Он сказал им на это: думаете ли вы, что эти\nГалилеяне были грешнее всех Галилеян, что так\nпострадали?","3":"Нет, говорю вам, но, если не будете каяться, все\nподобным же образом погибнете.","4":"Или те восемнадцать, на которых упала башня в\nСилоаме и убила их, – думаете ли вы, что они оказались\nбольшими должниками, чем все люди, живущие в\nИерусалиме?","5":"Нет, говорю вам, но если не покаетесь, все так же\nпогибнете.","6":"И сказал Он такую притчу: была у человека\nсмоковница, посаженная в винограднике его, и пришел\nон искать плода на ней, и не нашел;","7":"и сказал виноградарю: «вот три года, как я\nприхожу искать плода на этой смоковнице и не нахожу.\nСруби ее, к чему она и землю истощает?»","8":"Но тот сказал ему в ответ: «господин, оставь ее и\nна этот год, а я тем временем окопаю ее и унавожу,","9":"не даст ли плода на будущий год. Если же нет, ты\nее срубишь».","10":"И учил Он в одной из синагог в субботу.","11":"И вот, женщина, восемнадцать лет имевшая духа\nнемощи; и была она скорчена, и не могла как следует\nподнять голову.","12":"Увидев же ее, Иисус подозвал ее и сказал:\nженщина, ты свободна от недуга твоего,","13":"И\nвозложил\nна\nнее\nруки,\nи\nона\nтотчас\nвыпрямилась и стала славить Бога.","14":"В ответ на это начальник синагоги, негодуя, что\nИисус исцелил в субботу, сказал народу: есть шесть\nдней, в которые должно делать; в те и приходите\nисцеляться, а не в день субботний.","15":"И ответил ему Господь: лицемеры, не отвязывает\nли каждый из вас в субботу вола своего или осла от\nяслей и не ведет ли поить?","16":"А эту – дочь Авраамову, – которую связал сатана\nвот уже восемнадцать лет, не надлежало ли освободить\nот этих уз в день субботний?","17":"И когда Он говорил это, все противившиеся Ему\nстыдились, и вся толпа радовалась всем славным делам\nЕго.","18":"Итак, Он говорил: чему подобно Царство Божие,\nи чему уподоблю его?","19":"Подобно оно зерну горчичному, которое взял\nчеловек и бросил в саду своем, и выросло оно и стало\nдеревом, и птицы небесные свили себе гнёзда в ветвях\nего.","20":"И еще сказал: чему уподоблю Царство Божие?","21":"Подобно оно закваске, которую взяла женщина и\nположила в три меры муки, доколе не вскисло всё.","22":"И проходил Он по городам и селениям, уча и\nнаправляя путь в Иерусалим.","23":"Сказал же Ему некто: Господи, верно ли, что\nмало спасаемых? Он же сказал им:","24":"подвизайтесь войти узкой дверью, ибо многие,\nговорю вам, будут стараться войти и не смогут.","25":"Когда встанет хозяин дома и затворит дверь, и\nвы, стоя снаружи, начнете стучаться в дверь и\nговорить: «Господи, отвори нам», и Он ответит вам: «не\nзнаю вас, откуда вы», –","26":"тогда начнете вы говорить: «мы ели перед Тобою\nи пили, и на улицах наших Ты учил»,","27":"и скажет Он вам: «не знаю вас, откуда вы:\nотойдите от Меня, все делатели неправды».","28":"Там будет плач и скрежет зубов, когда увидите\nАвраама и Исаака и Иакова и всех пророков в Царстве\nБожием, а себя изгоняемыми вон.","29":"И придут с востока и запада, и с севера и юга, и\nвозлягут в Царстве Божием.","30":"И вот, есть последние, которые будут первыми, и\nесть первые, которые будут последними.","31":"В этот самый час подошли некоторые фарисеи и\nсказали Ему: выйди и уходи отсюда, потому что Ирод\nхочет Тебя убить.","32":"И он сказал им: пойдите, скажите этой лисице:\nвот, Я изгоняю бесов и исцеления совершаю сегодня и\nзавтра, и в третий день – свершение Мое.","33":"Но Мне надлежит быть в пути сегодня и завтра и\nв следующий день, ибо не может быть, чтобы пророк\nпогиб вне Иерусалима.","34":"Иерусалим, Иерусалим, убивающий пророков и\nкамнями побивающий посланных к нему! Сколько раз\nхотел Я собрать детей твоих, как птица свой выводок\nпод крылья, и вы не захотели.","35":"Вот, оставляется вам дом ваш пуст. Говорю же\nвам: не увидите Меня, доколе не скажете: «Благословен\nГрядущий во имя Господне»."},"14":{"1":"И было: когда Он пришел в субботу в дом одного\nиз\nначальников\nфарисейских\nвкусить\nхлеба,\nони\nнаблюдали за Ним.","2":"И вот, перед Ним человек, больной водянкой.","3":"И обратился Иисус к законникам и фарисеям,\nговоря: дозволяется ли уврачевать в субботу, или нет?","4":"Они промолчали. И прикоснувшись, Он исцелил\nего и отпустил.","5":"А им Он сказал: разве кто из вас, у кого сын или\nвол упадет в колодец, не тотчас вытащит его в день\nсубботний?","6":"И не смогли возразить на это.","7":"И говорил Он приглашенным притчу, замечая, как\nони выбирали себе первые места:","8":"когда позовет тебя кто-нибудь на брачный пир, не\nсадись на первое место; как бы не оказалось среди\nприглашенных им кого-нибудь почетнее тебя,","9":"и не пришел бы позвавший тебя и его и не сказал\nтебе: «дай ему место», и тогда ты займешь со стыдом\nпоследнее место.","10":"Но когда тебя позовут, пойди, и сядь на\nпоследнее место, чтобы, когда придет пригласивший\nтебя, он сказал тебе: «друг, передвинься повыше»:\nтогда будет тебе честь перед всеми возлежащими с\nтобою,","11":"потому что всякий возносящий себя смирён\nбудет, и смиряющий себя вознесён будет.","12":"Говорил же и пригласившему Его: когда ты\nустраиваешь обед или ужин, не зови друзей твоих, ни\nбратьев твоих, ни родственников твоих, ни соседей\nбогатых; как бы и они в ответ тебя не позвали, и не\nполучил бы ты воздаяния.","13":"Но когда делаешь угощение, зови нищих,\nувечных, хромых, слепых;","14":"и блажен будешь, что они не могут воздать тебе;\nибо воздается тебе в воскресение праведных.","15":"Услышав это, некто из возлежащих сказал Ему:\nблажен, кто вкусит хлеба в Царстве Божием.","16":"Он же сказал ему: сделал человек большой ужин\nи позвал многих.","17":"И послал раба своего в час ужина сказать\nприглашенным: «приходите, уже готово».","18":"И начали все как один извиняться. Первый сказал\nему: «я купил землю, и мне нужно пойти посмотреть ее.\nПрошу тебя, извини меня».","19":"И другой сказал: «я купил пять пар волов и иду\nиспытать их. Прошу тебя, извини меня».","20":"И третий сказал: «я женился и потому не могу\nпридти».","21":"И придя, раб сообщил это господину своему.\nТогда, разгневавшись, сказал хозяин дома рабу своему:\n«выйди поскорее на улицы и переулки города и введи\nсюда нищих, и увечных, и слепых, и хромых».","22":"И сказал раб: «господин, сделано то, что ты\nприказал, и еще есть место».","23":"И сказал господин рабу: «выйди на дороги и к\nизгородям, заставь людей войти, чтобы наполнился мой\nдом.","24":"Ибо говорю вам, что никто из мужей тех\nприглашенных не вкусит моего ужина».","25":"С Ним шло много народа, и обернувшись, Он\nсказал им:","26":"если кто приходит ко Мне и не ненавидит отца\nсвоего и матери, и жены, и детей, и братьев, и сестер, а\nтакже и души своей, не может быть Моим учеником.","27":"Кто не несет креста своего и не идет за Мною, не\nможет быть Моим учеником.","28":"Ибо кто из вас, желая построить башню, не сядет\nпрежде и не вычислит издержек: может ли он довести\nдо конца?","29":"Чтобы, когда он положит основание и не будет в\nсилах завершить, все видящие не начали бы смеяться\nнад ним,","30":"говоря: «этот человек начал строить и не был в\nсилах завершить».","31":"Или какой царь, идя на войну против другого\nцаря, не сядет и не посоветуется прежде, силен ли он с\nдесятью тысячами противостать идущему на него с\nдвадцатью тысячами?","32":"Если же – нет, то пока тот еще далеко, он\nотправляет посольство и спрашивает об условиях мира.","33":"Так и всякий из вас, если не откажется от всего,\nчто имеет, не может быть Моим учеником.","34":"Поэтому: соль хороша; но если и соль станет\nпресной, чем вернуть ей силу?","35":"Ни в землю, ни в навоз она не годится. Ее\nбросают вон. Имеющий уши слышать да слышит."},"15":{"1":"Приближались же к Нему все мытари и грешники\nслушать Его.","2":"И роптали фарисеи и книжники, говоря: Он\nпринимает грешников и ест с ними.","3":"И сказал Он им такую притчу:","4":"кто из вас, имея сто овец и потеряв одну из них,\nне покидает девяноста девяти в пустыне и не идет за\nпропавшей, доколе не найдет ее?","5":"И найдя, он берет ее на плечи радуясь,","6":"и придя к себе в дом, созывает друзей и соседей и\nговорит им: «порадуйтесь со мной, потому что я нашел\nовцу мою пропадавшую».","7":"Говорю вам, что так на небе радость будет больше\nоб одном грешнике кающемся, чем о девяноста девяти\nправедниках, которые не нуждаются в покаянии.","8":"Или какая женщина, имеющая десять драхм, если\nпотеряет одну драхму, не зажигает светильника и не\nметет дома и не ищет усердно, доколе не найдет?","9":"И найдя, она созывает подруг и соседок и говорит:\n«порадуйтесь со мной, потому что я нашла драхму,\nкоторую потеряла».","10":"Так, говорю вам, бывает радость пред ангелами\nБожиими об одном грешнике кающемся.","11":"И Он сказал: у одного человека было два сына,","12":"и сказал младший из них отцу: «отец, дай мне\nпричитающуюся мне часть состояния». И он разделил\nмежду ними имение.","13":"И спустя немного дней, собрав всё, младший сын\nуехал в страну далекую и там расточил свое состояние,\nживя разгульно.","14":"И когда он истратил всё, настал сильный голод в\nтой стране, и он начал нуждаться;","15":"и пошел, пристал к одному из граждан той\nстраны, и тот послал его на свои поля пасти свиней.","16":"И он рад был бы наполнить чрево свое рожками,\nкоторые ели свиньи, и никто не давал ему.","17":"И придя в себя, он сказал: «у скольких\nработников отца моего хлеб в изобилии, а я здесь\nпогибаю от голода.","18":"Встану, пойду к отцу моему и скажу ему: отец,\nсогрешил я против неба и пред тобою;","19":"я больше не достоин называться твоим сыном;\nпоступи со мной, как с любым из твоих работников».","20":"И он встал и пошел к отцу своему. И когда он был\nеще далеко, увидел его отец его и сжалился, и\nпобежав, пал на шею ему и поцеловал его.","21":"И сказал ему сын: «отец, согрешил я против неба\nи пред тобою; я больше не достоин называться твоим\nсыном».","22":"И сказал отец рабам своим: «скорее достаньте\nлучшую одежду и оденьте его, и дайте перстень на\nруку его и обувь на ноги,","23":"и приведите нашего откормленного теленка,\nзаколите, будем есть и веселиться,","24":"ибо этот сын мой мертв был и ожил, пропадал и\nнашелся». И начали веселиться.","25":"А сын его старший был в поле; и когда,\nвозвращаясь, приблизился к дому, услышал он музыку и\nпляску;","26":"и призвав одного из слуг, он спрашивал, что бы\nэто могло значить.","27":"И тот сказал ему: «брат твой пришел, и заколол\nотец твой нашего откормленного теленка, так как\nпринял его здоровым».","28":"Он рассердился и не хотел войти. И отец его\nвышел и стал просить его.","29":"А он ответил отцу: «вот, я столько лет служу\nтебе, и никогда заповеди твоей не преступал, и мне ты\nникогда не дал козленка, чтобы повеселиться мне с\nдрузьями моими,","30":"А когда пришел сын твой этот, проевший твое\nимение\nс\nблудницами,\nты\nзаколол\nдля\nнего\nоткормленного теленка».","31":"Он же сказал ему: «дитя мое, ты всегда со мною,\nи все мое – твое,","32":"но надо было возвеселиться и возрадоваться\nтому, что брат твой этот мертв был и ожил, пропадал и\nнашелся»."},"16":{"1":"Сказал Он и ученикам: был богатый человек, у\nкоторого был домоправитель, и на него донесли ему,\nчто он расточает его имущество.","2":"И призвав его, он сказал ему: «что это я слышу о\nтебе? Дай отчет в управлении твоем, ибо ты не можешь\nбольше управлять».","3":"И сказал себе самому домоправитель: «что мне\nделать? Господин мой отнимает у меня управление.\nРаботать лопатой не могу, просить милостыню стыжусь.","4":"Знаю, что сделаю, чтобы приняли меня в дома\nсвои, когда буду отставлен от управления».","5":"И призвав отдельно каждого из должников\nгосподина\nсвоего,\nговорит\nпервому:\n«сколько\nты\nдолжен господину моему?»","6":"Он сказал: «сто мер масла». И он сказал ему:\n«возьми твою расписку и садись, скорее напиши:\nпятьдесят».","7":"Потом другому сказал: «а ты сколько должен?»\nТот сказал: «сто мер пшеницы». Говорит ему: «возьми\nтвою расписку и напиши: восемьдесят».","8":"И\nпохвалил\nгосподин\nдомоправителя\nнеправедного за то, что умно поступил, потому что в\nобращении с людьми рода своего сыны века сего умнее\nсынов света.","9":"И Я говорю вам: сотворите себе друзей богатством\nнеправедным, чтобы, когда его не станет, они приняли\nвас в вечные обители,","10":"Верный в малом – и во многом верен, и\nнеправедный в малом – неправеден и во многом,","11":"Итак, если вы в неправедном богатстве не\nоказались верны, кто вверит вам то, что истинно?","12":"И если вы в чужом не оказались верны, кто вам\nдаст ваше?","13":"Никакой раб не может служить двум господам:\nили одного возненавидит, а другого возлюбит; или к\nодному привяжется, а другим пренебрежет. Не можете\nБогу служить и богатству.","14":"И слышали это всё фарисеи, которые были\nсребролюбивы, и высмеивали Его.","15":"И\nОн\nсказал\nим:\nвы\nвыставляете\nсебя\nправедными пред людьми, но Бог знает сердца ваши,\nибо высокое у людей – мерзость пред Богом.","16":"Закон и Пророки – до Иоанна: с того времени\nЦарство Божие благовествуется, и всякий усилием\nвходит в него.","17":"Но легче пройти небу и земле, чем одной черте\nпропасть в Законе.","18":"Всякий, отпускающий жену свою и женящийся на\nдругой,\nпрелюбодействует,\nи\nженящийся\nна\nотпущенной мужем прелюбодействует.","19":"Некий человек был богат, и одевался в порфиру и\nвиссон, и каждый день пиршествовал блистательно.","20":"Нищий же некий по имени Лазарь лежал у ворот\nего, покрытый язвами;","21":"и хотел он насытиться тем, что падало со стола\nбогача, и собаки приходили и лизали язвы его.","22":"И случилось, что умер нищий, и отнесли его\nангелы на лоно Авраамово. Умер и богач, и похоронили\nего;","23":"и в аду, пребывая в мучениях, поднял он глаза\nсвои и видит издали Авраама и Лазаря на лоне его.","24":"И воззвал он со всей силой: «отец Авраам,\nсмилуйся надо мной, и пошли Лазаря, чтобы он омочил\nконец пальца своего в воде и прохладил язык мой,\nпотому что я мучусь в этом пламени».","25":"Но Авраам сказал: «дитя мое, вспомни, что, как\nты получил благое твое в жизни твоей, так и Лазарь\nзлое. Теперь же он здесь утешается, а ты мучишься.","26":"И при всём том, между нами и вами утверждена\nвеликая пропасть, чтобы хотящие перейти отсюда к вам\nне могли, и оттуда к нам не переходили бы».","27":"И он сказал: «тогда прошу тебя, отец, послать\nего в дом отца моего,","28":"ибо\nесть\nу\nменя\nпять\nбратьев:\nпусть\nсвидетельствует им, чтобы и они не пришли в это место\nмучения».","29":"И говорит Авраам: «есть у них Моисей и Пророки:\nпусть послушают их».","30":"Он же сказал: «нет, отец Авраам, но если кто из\nмертвых придёт к ним, покаются».","31":"Но он сказал ему: «если Моисея и Пророков не\nслушают, то, когда бы и воскрес кто из мертвых, не\nубедятся они»."},"17":{"1":"И Он сказал ученикам Своим: невозможно, чтобы\nне пришли соблазны, но горе тому, чрез кого они\nприходят.","2":"Лучше было бы ему, если бы мельничный камень\nоблегал его шею, и был он ввержен в море, чем чтобы\nсоблазнил он одного из малых сих.","3":"Наблюдайте же за собой. Если согрешит брат\nтвой, выговори ему; и если покается, прости ему;","4":"и если семь раз в день согрешит против тебя и\nсемь раз в день возвратится к тебе и скажет: «каюсь», –\nпрости ему.","5":"И сказали апостолы Господу: прибавь нам веры.","6":"И сказал Господь: если бы вы имели веру с зерно\nгорчичное, – то сказали бы вы этой шелковице:\n«вырвись с корнем и пересадись в море», и она\nпослушалась бы вас.","7":"Кто из вас, имея раба пашущего или пасущего, по\nвозвращении его с поля, скажет ему: «иди сейчас же,\nсадись за стол»?","8":"Напротив, не скажет ли он ему: «приготовь мне\nпообедать и, подпоясавшись, служи мне, пока я ем и\nпью, и потом ешь и пей ты сам»?","9":"Будет ли он благодарить раба за то, что тот\nисполнил указанное?","10":"Так и вы, когда исполните всё указанное вам,\nговорите: «мы рабы ни на что не годные; что должны\nбыли сделать, сделали».","11":"И было: на пути в Иерусалим, шел Он вдоль\nграницы Самарии и Галилеи.","12":"И когда входил Он в одно селение, встретили Его\nдесять человек прокаженных, которые остановились\nпоодаль.","13":"И заговорили они громким голосом: Иисус\nНаставник, помилуй нас.","14":"И увидев, Он сказал им: пойдите, покажитесь\nсвященникам. И было: пока они шли, очистились.","15":"Один\nже\nиз\nних,\nувидев,\nчто\nисцелен,\nвозвратился, громким голосом прославляя Бога.","16":"И пал на лицо свое к Его ногам, благодаря Его; и\nто был Самарянин.","17":"И сказал Иисус в ответ: не десять ли очистились?\nГде же девять?","18":"Не нашлось никого, кто возвратился бы воздать\nславу Богу, кроме этого иноплеменника?","19":"И сказал ему: встань, иди; вера твоя спасла тебя.","20":"И на вопрос фарисеев, когда придет Царство\nБожие, Он ответил им: не придет Царство Божие\nприметным образом,","21":"и не скажут: «вот здесь», или: «там». Ибо, вот,\nЦарство Божие внутри вас.","22":"И сказал ученикам: придут дни, когда восхотите\nувидеть один только день Сына Человеческого и не\nувидите.","23":"И скажут вам: «вот там», «вот здесь», – не\nходите и не гоняйтесь.","24":"Ибо как молния, блистая, светит от одного края\nнеба до другого, так будет Сын Человеческий в день\nСвой.","25":"Но прежде надлежит Ему много претерпеть и\nбыть отвергнутым родом этим.","26":"И как было в дни Ноя, так будет и в дни Сына\nЧеловеческого:","27":"ели, пили, женились, выходили замуж – до того\nдня, как вошел Ной в ковчег, и пришел потоп и погубил\nвсех.","28":"Так же, как было в дни Лота: ели, пили,\nпокупали, продавали, сажали, строили;","29":"а в тот день, как вышел Лот из Содома,\nпролились дождем огонь и сера с неба и погубили всех.","30":"Так будет и в тот день, когда Сын Человеческий\nявится.","31":"В тот день, кто будет на крыше, а вещи его в\nдоме, да не спускается взять их; также и тот, кто в\nполе, да не возвращается назад.","32":"Помните о жене Лота.","33":"Кто будет стараться душу свою сохранить, тот\nпогубит ее, и кто погубит, тот оживит ее.","34":"Говорю вам, в эту ночь будут двое на одной\nпостели: один будет взят, а другой оставлен.","35":"Две будут вместе молоть: одна будет взята,\nдругая же оставлена.","36":"Стих 36 прежних русских переводов: «двое в\nполе: один будет взят, а другой оставлен», почти\nсовпадающий с Мф.24.40, отсутствует в древнейших\nрукописях Лк.","37":"И говорят они Ему на это: где, Господи? Он же\nсказал им: где тело, там соберутся и орлы."},"18":{"1":"И сказал Он им притчу о том, что надо им всегда\nмолиться и не унывать:","2":"в городе был судья, Бога не боявшийся и людей не\nстыдившийся.","3":"И была в городе том вдова, и приходила она к\nнему и говорила: «защити меня от противника моего».","4":"И он долго не хотел. А потом сказал самому себе:\n«хотя я Бога не боюсь и людей не стыжусь,","5":"но так как эта вдова не оставляет меня в покое,\nзащищу ее, чтобы она, в конце концов, не стала меня\nбить».","6":"И сказал Господь: послушайте, что говорит судья\nнеправедный.","7":"Разве Бог не окажет защиты избранным Своим,\nвопиющим к Нему день и ночь? И Он являет им Свое\nдолготерпение.","8":"Говорю вам, что окажет им защиту вскоре. Но Сын\nЧеловеческий, придя, найдет ли веру на земле?","9":"Сказал же и некоторым, уверенным в собственной\nправедности и уничижавшим остальных, такую притчу:","10":"два человека вошли в храм помолиться, один –\nфарисей, а другой – мытарь.","11":"Фарисей, став, молился про себя так: «Боже,\nблагодарю Тебя, что я не как прочие люди: грабители,\nобманщики, прелюбодеи, или даже как этот мытарь:","12":"пощусь два раза в неделю, даю десятину от\nвсего, что приобретаю».","13":"Мытарь же, стоя вдали, не смел даже глаз\nподнять на небо, но бил себя в грудь и говорил: «Боже,\nбудь милостив ко мне, грешнику».","14":"Говорю\nвам:\nэтот\nпришел\nв\nдом\nсвой\nоправданным, а не тот. Ибо всякий, возносящий себя,\nсмирён будет, а смиряющий себя вознесён будет.","15":"Приносили же к Нему и младенцев, чтобы Он к\nним прикасался. Увидев это, ученики не позволяли им.","16":"Но Иисус подозвал детей и сказал: пустите детей\nприходить ко Мне и не препятствуйте им; ибо таковых\nесть Царство Божие.","17":"Истинно говорю вам: кто не примет Царства\nБожия как дитя, тот не войдет в него.","18":"И спросил Его некий начальник: Учитель благой,\nчто я должен сделать, чтобы наследовать жизнь\nвечную?","19":"И сказал ему Иисус: что ты Меня называешь\nблагим? Никто не благ, кроме одного Бога.","20":"Ты знаешь заповеди: «Не прелюбодействуй, не\nубей, не укради, не лжесвидетельствуй, почитай отца\nтвоего и мать».","21":"Он же сказал: всё это я сохранил от юности.","22":"Услышав, Иисус сказал ему: еще одного тебе не\nхватает: всё, что имеешь, продай и раздай нищим, и\nбудешь иметь сокровище на небесах, и приходи, следуй\nза Мною.","23":"Услышав же это, он сильно опечалился, ибо был\nвесьма богат.","24":"Увидев его печаль, Иисус сказал: как трудно\nимеющим богатство входить в Царство Божие.","25":"Ибо легче верблюду войти в ушко иглы, чем\nбогатому войти в Царство Божие.","26":"И сказали услышавшие: кто же может быть\nспасен?","27":"Он же сказал: невозможное людям возможно\nБогу.","28":"И сказал Петр: вот, мы, оставив то, что имели,\nпоследовали за Тобою.","29":"Он же сказал им: истинно говорю вам, что нет\nникого, кто, оставив дом, или жену, или братьев, или\nродителей, или детей ради Царства Божия,","30":"не получил бы во много раз больше во время сие,\nа в веке грядущем – жизнь вечную.","31":"Отозвав же Двенадцать, Он сказал им: вот, мы\nвосходим в Иерусалим, и свершится всё написанное\nчрез пророков о Сыне Человеческом:","32":"ибо Он будет предан язычникам и подвергнется\nпоруганию и оскорблению и оплеванию,","33":"и, по бичевании, убьют Его, и в день третий Он\nвоскреснет.","34":"И они ничего из этого не поняли, и слово это\nбыло сокрыто от них, и не разумели они того, что\nговорилось.","35":"И было: когда приближался Он к Иерихону,\nкакой-то слепой сидел у дороги, прося милостыни.","36":"И услышав, что мимо проходит народ, он\nспрашивал: что это такое?","37":"И возвестили ему, что проходит Иисус Назорей.","38":"И он воззвал: Иисус, Сын Давидов! Помилуй\nменя!","39":"И шедшие впереди требовали от него, чтобы он\nумолк, но он еще больше кричал: Сын Давидов, помилуй\nменя!","40":"И остановился Иисус и велел привести его к\nНему. И когда тот приблизился, Он спросил его:","41":"что ты хочешь, чтобы Я тебе сделал? Он же\nсказал: Господи, чтобы я прозрел.","42":"И сказал ему Иисус: прозри! Вера твоя спасла\nтебя.","43":"И он тотчас прозрел и последовал за Ним, славя\nБога. И весь народ, видя это, воздал хвалу Богу."},"19":{"1":"И Он вошел в Иерихон и проходил через город.","2":"И вот был человек, по имени Закхей, и он был\nстарший мытарь, и был он богат.","3":"И старался он увидеть Иисуса, кто Он, и не мог из-\nза толпы, потому что был ростом мал.","4":"И забежав вперед, взлез на сикомору, чтобы\nувидеть Его, так как Он должен был проходить той\nдорогой.","5":"И придя на это место, Иисус посмотрел наверх и\nсказал ему: Закхей, поспеши слезть, ибо сегодня надо\nМне быть у тебя в доме.","6":"И он слез поспешно, и принял Его с радостью.","7":"И увидев, все начали роптать и говорили: Он\nостановился у человека грешника.","8":"А Закхей встал и сказал Господу: вот, половину\nтого, что имею, Господи, я даю нищим, и если у кого что\nнеправедно вынудил, возмещу вчетверо.","9":"И сказал ему Иисус: ныне пришло спасение дому\nсему, потому что и он сын Авраамов,","10":"ибо Сын Человеческий пришел взыскать и спасти\nпогибшее.","11":"Когда же они слушали это, Он сказал еще\nпритчу, потому что был Он близко от Иерусалима, и они\nдумали, что Царство Божие должно теперь же явиться.","12":"Он\nсказал:\nнекий\nчеловек\nзнатного\nрода\nотправился в дальнюю страну, чтобы получить себе\nцарство и возвратиться.","13":"Призвав же десять слуг своих, он дал им десять\nмин и сказал им: «пустите их в оборот, пока я не\nприду».","14":"Но сограждане ненавидели его и отправили\nвслед за ним посольство, чтобы сказать: «не хотим,\nчтобы этот воцарился над нами».","15":"И было: когда он возвратился, получив царство,\nприказал он позвать к нему тех слуг, которым дал\nденьги, чтобы узнать, кто что приобрел.","16":"И явился первый и сказал: «господин, мина твоя\nдала десять мин».","17":"И он сказал ему: «хорошо, добрый слуга; за то,\nчто ты в малом оказался верен, властвуй над десятью\nгородами».","18":"И пришел второй и сказал: «мина твоя, господин,\nпринесла пять мин».","19":"Сказал же и этому: «и ты будь над пятью\nгородами».","20":"И другой пришел и сказал: «господин, вот мина\nтвоя, которую я хранил в платке;","21":"ибо я боялся тебя, потому что ты человек\nнепреклонный: берешь, чего не клал, и жнешь, чего не\nсеял».","22":"Говорит ему: «твоими устами буду судить тебя,\nлукавый слуга! Ты знал, что я человек непреклонный:\nберу, чего не клал, и жну, чего не сеял.","23":"Почему же ты не дал денег моих в оборот? И я,\nпридя, получил бы их с ростом».","24":"И он сказал бывшим при нем: «возьмите от него\nмину и дайте имеющему десять мин».","25":"И сказали они ему: «господин, у него десять\nмин».","26":"«Говорю вам, что всякому имеющему дано будет,\nа у неимеющего будет взято и то, что он имеет.","27":"А врагов моих этих, не пожелавших, чтобы я\nвоцарился над ними, приведите сюда и заколите передо\nмною».","28":"И сказав это, Он пошел дальше, восходя в\nИерусалим.","29":"И было: когда Он приблизился к Виффагии и\nВифании на склоне горы, называемой Елеон, послал Он\nдвух из учеников","30":"и сказал: идите в селение напротив, при входе в\nкоторое найдете осленка привязанного, на которого\nникогда никто из людей не садился, и отвязав его,\nприведите.","31":"И\nесли\nкто\nспросит\nвас:\n«почему\nвы\nотвязываете?» – вы скажете так: «потому что он нужен\nГосподу».","32":"Посланные пошли и нашли, как Он сказал им.","33":"Когда же они отвязывали осленка, хозяева его\nсказали им: что вы отвязываете осленка?","34":"Они же сказали: он нужен Господу.","35":"И привели его к Иисусу; и накинув одежды свои\nна осленка, посадили Иисуса.","36":"И когда Он ехал, люди постилали одежды свои\nпо дороге.","37":"И когда Он приближался уже к спуску с горы\nМасличной, всё множество учеников в радости громким\nголосом начало восхвалять Бога за все чудеса, какие\nони видели,","38":"говоря: Благословен Грядущий, Царь, во имя\nГосподне; на небе мир, и слава в вышних.","39":"И некоторые из фарисеев сказали Ему из толпы:\nУчитель, запрети ученикам Твоим.","40":"А Он ответил: говорю вам: если они умолкнут,\nкамни возопиют.","41":"И когда Он приблизился, то, увидев город,\nзаплакал над ним","42":"и сказал: если бы познал в сей день и ты, что\nведет к миру, но теперь это сокрыто от глаз твоих.","43":"Ибо придут на тебя дни, когда враги твои\nвозведут против тебя укрепления и окружат тебя и\nстеснят тебя отовсюду,","44":"и повергнут на землю тебя и детей твоих в тебе,\nи не оставят в тебе камня на камне, за то, что ты не\nузнал времени посещения твоего.","45":"И войдя в храм, Он начал изгонять продающих,","46":"говоря им: написано: «И будет дом Мой домом\nмолитвы», вы же его сделали вертепом разбойников.","47":"И учил каждый день в храме. Первосвященники\nже и книжники искали Его погубить – также и первые\nлюди народа, –","48":"и не знали, как поступить, ибо весь народ не\nотходя слушал Его."},"20":{"1":"И было: однажды, когда Он учил народ в храме и\nблаговествовал,\nприступили\nпервосвященники\nи\nкнижники со старейшинами","2":"и сказали Ему так: скажи нам, какою властью Ты\nэто делаешь, или кто Он, давший Тебе эту власть?","3":"Он же сказал им в ответ: спрошу и Я вас об одном,\nи скажите Мне:","4":"крещение Иоанново с неба было или от людей?","5":"Они же так судили между собой: если скажем: «с\nнеба», Он скажет: «почему вы не поверили ему?»","6":"Если же скажем: «от людей», то весь народ побьет\nнас камнями, ибо он уверен, что Иоанн – пророк.","7":"И они ответили, что не знают, откуда.","8":"И Иисус сказал им: и Я вам не скажу, какою\nвластью это делаю.","9":"И начал говорить народу такую притчу: человек\nнасадил виноградник и сдал его виноградарям и уехал\nнадолго.","10":"И в свое время послал к виноградарям раба,\nчтобы\nдали\nему\nот\nплодов\nвиноградника,\nно\nвиноградари прибили его и отослали ни с чем.","11":"И он сделал больше: другого раба послал, но они\nи того, прибив и обесчестив, отослали ни с чем;","12":"и он сделал еще больше: третьего послал, но и\nэтого они, изранив, выгнали.","13":"И сказал господин виноградника: «что мне\nделать? Пошлю сына моего возлюбленного. Может\nбыть, его устыдятся».","14":"Но увидев его, виноградари стали рассуждать\nмежду собой, говоря: «это наследник; убьем его, чтобы\nнаследство стало нашим».","15":"И выбросив его вон из виноградника, убили. Что\nже сделает с ними господин виноградника?","16":"Придет и предаст смерти виноградарей этих и\nотдаст виноградник другим. Услышав это, они сказали:\nда не будет!","17":"Он же, взглянув на них, сказал: что значит это\nслово Писания: «Камень, который отвергли строители,\nон сделался главою угла»?","18":"Всякий, кто упадет на этот камень, разобьется, а\nна кого он упадет, того обратит в прах.","19":"И вознамерились книжники и первосвященники\nсейчас же наложить на Него руки, но побоялись народа,\nибо поняли, что о них Он сказал эту притчу.","20":"И установив надзор, они подослали своих людей,\nпринимавших видимость праведных, с целью изловить\nЕго на слове так, чтобы предать Его начальству и\nвласти правителя.","21":"И спросили они Его, говоря: Учитель, мы знаем,\nчто Ты правильно говоришь и учишь и не допускаешь\nлицеприятия, но воистину пути Божию учишь.","22":"Можно ли нам платить кесарю налог или нет?","23":"Он же, уразумев их хитрость, сказал им:","24":"покажите Мне динарий: чье на нем изображение\nи надпись? Они же сказали: кесаря.","25":"И Он сказал им: итак, отдавайте кесарево\nкесарю, а Божие Богу.","26":"И не смогли они изловить Его на слове перед\nнародом и, удивившись ответу Его, замолчали.","27":"И\nподошли\nнекоторые\nиз\nсаддукеев,\nутверждающие, что воскресения нет, и спросили Его:","28":"Учитель, Моисей написал нам: «Если у кого умрет\nбрат, имея жену, и если он бездетен, да возьмет брат\nего жену и восстановит семя брату своему».","29":"Итак, было семь братьев: и первый, взяв жену,\nумер бездетным;","30":"и второй,","31":"и третий взял ее, также и все семеро, и не\nоставили детей и умерли.","32":"Наконец и жена умерла.","33":"Итак, в воскресение, которого из них будет она\nженой? Ибо все семеро имели ее женой.","34":"И сказал им Иисус: сыны века сего женятся и\nвыходят замуж.","35":"А те, которые удостоены будут достичь века того\nи воскресения из мертвых, не женятся, и замуж не\nвыходят,","36":"ибо и умереть уже не могут: ибо равны они\nангелам,\nи\nсыны\nони\nБожии,\nбудучи\nсынами\nвоскресения.","37":"А что восстают мертвые, – и Моисей показал в\nповествовании о купине, когда он называет Господа\nБогом Авраама и Богом Исаака и Богом Иакова.","38":"Он – Бог не мертвых, но живых; ибо у Него все\nживы.","39":"На это некоторые из книжников сказали:\nУчитель, Ты хорошо сказал.","40":"Ибо они уже не смели спрашивать Его ни о чем. А\nОн сказал им:","41":"как говорят, что Христос есть Сын Давидов?","42":"Ибо сам Давид говорит в книге Псалмов: «Сказал\nГосподь Господу моему: сядь по правую сторону Мою,","43":"доколе Я не положу врагов Твоих в подножие ног\nТвоих».","44":"Итак, Давид называет Его Господом. Так как же\nОн сын его?","45":"И когда слушал весь народ, Он сказал ученикам:","46":"остерегайтесь книжников, имеющих пристрастие\nк\nдлинным\nодеждам\nи\nлюбящих\nприветствия\nна\nплощадях и первые сидения в синагогах и первые места\nна званых обедах;","47":"которые поедают дома вдов и для вида долго\nмолятся: эти примут большее осуждение."},"21":{"1":"И подняв глаза Свои, Он увидел богатых, клавших\nдары свои в сокровищницу.","2":"И увидел Он, что какая-то бедная вдова кладет\nтуда две лепты,","3":"и сказал: истинно говорю вам: вдова эта бедная\nбольше всех положила;","4":"ибо все они от избытка своего положили в\nдарохранилище, она же от скудости своей положила\nвсё, что имела на жизнь.","5":"И когда некоторые говорили о храме, что он\nукрашен красивыми камнями и приношениями, Он\nсказал:","6":"придут дни, когда из того, что вы видите здесь, не\nостанется камня на камне, который не будет опрокинут.","7":"И спросили Его: Учитель, когда же это будет? И\nкакое будет знамение, когда этому должно быть?","8":"Он же сказал: смотрите, чтобы не ввели вас в\nзаблуждение. Ибо многие придут под именем Моим,\nговоря: «это Я», и: «время близко». Не идите за ними.","9":"Когда же услышите о войнах и смутах, не\nприходите в ужас: ибо это должно произойти в начале,\nно не тотчас конец.","10":"Тогда говорил им: восстанет народ на народ и\nцарство на царство;","11":"будут и великие землетрясения, и по местам мор\nи голод, будут и страшные явления и с неба великие\nзнамения.","12":"Но ранее всего этого будут налагать на вас руки\nсвои и гнать, предавая в синагоги и тюрьмы, отводя к\nцарям и правителям за имя Мое.","13":"Приведет это вас к свидетельству.","14":"Итак, положите себе на сердце не обдумывать\nзаранее, что сказать в свою защиту,","15":"ибо Я дам вам уста и премудрость, которой не\nсможет ни противостать, ни воспрекословить ни один\nиз противящихся вам.","16":"И будете преданы и родителями, и братьями, и\nродственниками, и друзьями. И некоторых из вас\nумертвят.","17":"И будете ненавидимы всеми за имя Мое.","18":"Но и волос с головы вашей не пропадет.","19":"Терпением вашим вы приобретете души ваши.","20":"Когда же увидите, что Иерусалим окружен\nвойсками, тогда знайте, что близко запустение его.","21":"Тогда находящиеся в Иудее да бегут в горы; и\nкто в самом Иерусалиме, выходи из него; и кто в\nселениях, не входи в него,","22":"ибо это дни отмщения, чтобы исполнилось всё\nнаписанное.","23":"Горе имеющим во чреве и кормящим грудью в те\nдни; ибо будет нужда великая на земле и гнев на народ\nэтот;","24":"и падут от острия меча и будут отведены в плен\nво все народы, и Иерусалим будет попираем народами,\nдоколе не окончатся времена народов.","25":"И будут знамения на солнце и луне и звездах, и\nна земле томление народов в смятении от шума\nморского и волнения,","26":"когда люди будут бездыханны от страха и\nожидания того, что надвигается на вселенную: ибо\nсилы небесные будут поколеблены.","27":"И тогда увидят Сына Человеческого, грядущего\nна облаке с силою и славою великою.","28":"Когда же начнет это сбываться, встаньте и\nподнимите головы ваши, ибо приближается избавление\nваше.","29":"И\nсказал\nОн\nим\nпритчу:\nпосмотрите\nна\nсмоковницу и на все деревья:","30":"когда они уже распускаются, то, видя это, вы\nсами знаете, что уже близко лето.","31":"Так и вы, когда увидите, что это сбывается,\nзнайте, что близко Царство Божие.","32":"Истинно говорю вам: не пройдет род сей, доколе\nвсё не сбудется,","33":"Небо и земля пройдут; слова же Мои не пройдут.","34":"Наблюдайте же за собою, чтобы сердца ваши не\nотягчились\nхмелем\nи\nопьянением\nи\nзаботами\nжитейскими, и чтобы не настиг вас внезапно день тот,","35":"как сеть. Ибо найдет он на всех живущих по лицу\nвсей земли.","36":"Бодрствуйте же, постоянно молясь, чтобы быть в\nсилах избежать всего этого, имеющего наступить, и\nстать пред Сыном Человеческим.","37":"Днем Он учил в храме, а ночи, выходя, проводил\nна горе, называемой Елеон,","38":"и весь народ с утра приходил к Нему в храм\nслушать Его."},"22":{"1":"Приближался\nже\nпраздник\nОпресноков,\nназываемый Пасхою.","2":"И искали первосвященники и книжники, как бы\nубить Его, ибо они боялись народа.","3":"И вошел сатана в Иуду, называемого Искариотом,\nодного из числа Двенадцати;","4":"и он пошел совещаться с первосвященниками и\nначальниками стражи, как бы предать Его им.","5":"И они обрадовались и согласились дать ему денег.","6":"И он обещал и искал случая предать им Его не при\nнароде.","7":"Настал же день Опресноков, когда надлежало\nзакалать пасхального агнца;","8":"и Он послал Петра и Иоанна, сказав: пойдите,\nприготовьте нам пасху, чтобы нам вкусить ее.","9":"Они же сказали Ему: где велишь нам приготовить?","10":"И Он сказал им: вот, когда будете входить в\nгород, встретится вам человек с кувшином воды;\nпоследуйте за ним в дом, куда он войдет;","11":"и скажете хозяину дома: «говорит тебе Учитель:\nгде покой, в котором Я вкусил бы пасху с учениками\nМоими?»","12":"И он вам покажет горницу большую, убранную;\nтам приготовьте.","13":"Они пошли и нашли, как Он указал им, и\nприготовили пасху.","14":"И когда настал час, Он возлег, и апостолы с Ним.","15":"И Он сказал им: великим желанием возжелал Я\nвкусить эту пасху вместе с вами прежде Моего\nстрадания:","16":"ибо, говорю вам, не буду вкушать ее, доколе не\nисполнится она в Царстве Божием.","17":"И взяв чашу, возблагодарив, сказал: возьмите ее\nи разделите между собою,","18":"ибо говорю вам, что не буду пить отныне от\nплода лозы виноградной, доколе Царство Божие не\nпридет.","19":"И взяв хлеб, возблагодарив, преломил и дал им,\nговоря: это есть тело Мое, за вас отдаваемое. Делайте\nэто в воспоминание о Мне.","20":"Также и чашу после вечери, говоря: эта чаша\nесть новый завет в крови Моей, за вас изливаемой.","21":"Но вот рука предающего Меня со Мною за\nстолом,","22":"ибо Сын Человеческий идет по предназначению,\nно горе человеку тому, чрез которого Он предается.","23":"И они начали спрашивать друг друга: кто же из\nних сделает это?","24":"Возник и спор между ними, кто из них должен\nсчитаться большим.","25":"Он же сказал им: цари народов господствуют над\nними,\nи\nимеющие\nвласть\nнад\nними\nназываются\n«Благодетелями».","26":"А вы не так: но больший между вами да будет\nкак младший, и начальствующий как служащий.","27":"Ибо кто больше: возлежащий или служащий? Не\nвозлежащий ли? А Я посреди вас – как служащий.","28":"Но\nвы\nте,\nкоторые\nпребыли\nсо\nМною\nв\nиспытаниях Моих;","29":"и Я завещаю вам, как завещал Мне Отец Мой,\nЦарство,","30":"чтобы вы ели и пили за трапезою Моею в Царстве\nМоем. И сядете вы на престолах и будете судить\nдвенадцать колен Израилевых.","31":"И сказал Господь: Симон, Симон, вот, сатана\nдобился того, чтобы просеять вас, как пшеницу:","32":"но Я молился о Тебе, чтобы не оскудела вера\nтвоя, и ты некогда, обратившись, утверди братьев\nтвоих,","33":"Он же сказал Ему: Господи, с Тобою я готов и в\nтюрьму и на смерть идти.","34":"Но Он сказал: говорю тебе, Петр: не пропоет\nсегодня петух, как ты трижды отречешься, что не\nзнаешь Меня.","35":"И сказал им: когда Я послал вас без мешка и\nсумы и обуви, имели ли вы в чем недостаток? Они\nсказали: ни в чем.","36":"И Он сказал им: но теперь, у кого есть мешок,\nпусть возьмет; также и суму; и у кого нет, пусть\nпродаст одежду свою и купит меч;","37":"ибо говорю вам: нужно, чтобы совершилось на\nМне это слово Писания: «И к беззаконным причтен». Ибо\nи то, что о Мне, приходит к концу.","38":"Они же сказали: Господи, вот здесь два меча. И\nОн сказал им: довольно.","39":"И выйдя, пошел, по обыкновению, на гору\nМасличную; за Ним последовали и ученики.","40":"И придя на место, Он сказал им: молитесь, чтобы\nне впасть в искушение.","41":"А Сам отошел от них на расстояние брошенного\nкамня; и преклонив колени, молился,","42":"говоря: Отче, если хочешь, пронеси эту чашу\nмимо Меня; впрочем, не Моя воля, но Твоя да будет.","43":"И явился Ему ангел с неба, укрепляя Его.","44":"И впав в томление, усиленнее молился; и\nсделался пот Его, как капли крови, падающие на землю.","45":"И встав от молитвы, придя к ученикам, нашел их\nспящими от печали.","46":"И сказал им: что вы спите? Встаньте и молитесь,\nчтобы не впасть вам в искушение.","47":"Пока Он еще говорил, вот толпа, и тот, кого\nзвали Иуда, один из Двенадцати, шел впереди их. И он\nприблизился к Иисусу, чтобы поцеловать Его.","48":"Иисус же сказал ему: Иуда, поцелуем ли\nпредаешь ты Сына Человеческого?","49":"Окружавшие Его, увидев, что будет, сказали:\nГосподи, что, если мы ударим мечом?","50":"И один из них ударил первосвященникова раба и\nотсек ему правое ухо.","51":"Иисус же сказал в ответ: оставьте, довольно! И\nкоснувшись уха, исцелил раба.","52":"И\nсказал\nИисус\nпришедшим\nна\nНего\nпервосвященникам и начальникам храмовой стражи и\nстарейшинам: как на разбойника вышли вы с мечами и\nкольями.","53":"Каждый день бывал Я с вами в храме, и вы не\nподняли на Меня рук; но этот час – ваш, и власть тьмы.","54":"Взяв Его, повели и ввели в дом первосвященника.\nПетр же следовал издали.","55":"Когда развели огонь среди двора и сели вместе,\nсидел и Петр между ними.","56":"И одна служанка, увидев его, сидящего у огня, и\nвсмотревшись в него, сказала: и этот был с Ним.","57":"Но он отрекся и сказал: я не знаю Его, женщина.","58":"И немного спустя другой, увидев его, сказал: и\nты из них. Но Петр сказал: человек, я не из них.","59":"И около часа спустя кто-то другой начал\nнастойчиво утверждать: поистине, и этот был с Ним; он,\nведь, и Галилеянин.","60":"Но Петр сказал: человек, я не знаю, что ты\nговоришь. И тотчас, пока он еще говорил, пропел петух.","61":"И обернувшись, Господь взглянул на Петра. И\nвспомнил Петр слово Господне, как Он сказал ему:\nсегодня, прежде чем пропоет петух, ты отречешься от\nМеня трижды.","62":"И выйдя вон, плакал горько.","63":"А люди, державшие Иисуса, ругались над Ним и\nбили Его;","64":"и закрыв лицо Его, спрашивали: прореки, кто\nударил Тебя?","65":"И много иных хулений произносили на Него.","66":"И когда настал день, собрался совет старейшин\nнарода: и первосвященники, и книжники; и привели Его\nв свой синедрион.","67":"И сказали: если Ты Христос, скажи нам. Он же\nсказал им: если Я вам скажу, вы не поверите;","68":"а если спрошу, вы не ответите.","69":"Отныне Сын Человеческий будет восседать по\nправую сторону силы Божией.","70":"И сказали все: итак, Ты – Сын Божий? А Он им\nсказал: вы говорите, что Я.","71":"Они же сказали: какая нам еще нужда в\nсвидетельстве? Ибо мы сами слышали из уст Его."},"23":{"1":"И встало все их собрание, и повели Его к Пилату;","2":"и начали обвинять Его, говоря: мы нашли, что Этот\nЧеловек возмущает наш народ: запрещает платить\nналоги кесарю и называет Себя Христом Царем,","3":"Пилат спросил Его: Ты Царь Иудейский? Он же\nсказал ему в ответ: ты говоришь.","4":"И Пилат сказал первосвященникам и народу: я не\nнахожу никакой вины в Этом Человеке.","5":"Но они настаивали, говоря, что Он возбуждает\nнарод, уча по всей Иудее, начав с Галилеи, до этого\nместа.","6":"Пилат же, когда услышал, спросил: Этот Человек\nГалилеянин?","7":"И узнав, что Он из области Ирода, отослал Его к\nИроду, который и сам был в Иерусалиме в эти дни.","8":"Ирод же, увидев Иисуса, очень обрадовался, ибо\nуже довольно давно желал он увидеть Его, потому что\nслышал о Нем; и надеялся он увидеть от Него какое-\nнибудь знамение.","9":"И задавал Ему много вопросов. Но Он ничего не\nответил ему.","10":"И\nстояли\nпервосвященники\nи\nкнижники,\nусиленно обвиняя Его.","11":"Ирод же со своими воинами, уничижив Его и\nнадругавшись, нарядив в блестящую одежду, возвратил\nЕго Пилату.","12":"И стали друзьями между собой Ирод и Пилат в\nэтот самый день, ибо раньше они были во вражде друг с\nдругом.","13":"Пилат\nже,\nсозвав\nпервосвященников\nи\nначальников и народ,","14":"сказал им: вы привели ко мне Этого Человека,\nкак\nсмущающего\nнарод;\nи\nвот\nя,\nпроизведя\nрасследование в вашем присутствии, не нашел за Этим\nЧеловеком никакой вины из тех, что вы выставляете\nпротив Него.","15":"Но не нашел и Ирод, ибо он отослал Его к нам. И\nвот, ничего достойного смерти Он не совершил.","16":"Итак, наказав Его, отпущу.","17":"А ему нужно было отпустить им на Праздник\nодного.","18":"Но они всей толпой закричали: смерть Ему, а\nотпусти нам Варавву.","19":"Варавва был брошен в тюрьму за какой-то\nпроисшедший в городе мятеж и убийство.","20":"И снова Пилат обратился к ним с речью, желая\nотпустить Иисуса.","21":"Они же кричали: распни, распни Его!","22":"А он в третий раз сказал им: какое же зло сделал\nОн? Никакой вины, достойной смерти, я не нашел в Нем;\nитак, наказав Его, отпущу.","23":"Но они настаивали с громкими криками, требуя,\nчтобы Он был распят. И крики их всё усиливались.","24":"И Пилат решил исполнить их требование:","25":"отпустил сидевшего в тюрьме за мятеж и\nубийство, которого они требовали, а Иисуса предал в их\nволю.","26":"И когда они повели Его, то, захватив некоего\nСимона Киринеянина, шедшего с поля, возложили на\nнего крест, чтобы нес за Иисусом.","27":"Следовало же за Ним великое множество народа\nи женщин, которые били себя в грудь и плакали о Нем.","28":"И обернувшись к ним, Иисус сказал: дочери\nИерусалимские, не плачьте о Мне; но о себе плачьте и о\nдетях ваших,","29":"ибо вот приходят дни, когда скажут: «блаженны\nнеплодные и утробы, никогда не рождавшие, и сосцы,\nникогда не питавшие!»","30":"Тогда начнут говорить горам: «падите на нас!» и\nхолмам: «покройте нас!»","31":"Ибо если с зеленеющим деревом это делают, то с\nсухим что будет?","32":"Вели и двух других злодеев на смерть вместе с\nНим.","33":"И когда пришли на место, называемое Лобным,\nтам распяли Его и злодеев: одного справа, другого\nслева.","34":"Иисус же говорил: Отче, прости им, ибо не знают\nони, что делают. И деля между собой одежды Его,\nбросали жребий.","35":"И стоял народ и смотрел. Глумились же и\nначальники, говоря: других спас, пусть спасет Себя\nСамого, если Он Христос Божий, Избранник.","36":"Надругались над Ним и воины, подходя, поднося\nЕму уксус","37":"и говоря: если Ты Царь Иудейский, спаси Себя\nСамого.","38":"Была же и надпись над Ним письменами\nгреческими, римскими и еврейскими: Это – Царь\nИудейский.","39":"И один из повешенных злодеев хулил Его: разве\nТы не Христос? Спаси Себя Самого и нас.","40":"Другой же, укоряя, сказал ему в ответ: не\nбоишься ты Бога, ведь сам ты приговорен к тому же.","41":"И мы-то – справедливо, ибо достойное по делам\nнашим получаем. Он же ничего дурного не сделал.","42":"И говорил он: Иисус, вспомни о мне, когда Ты\nпридешь как Царь.","43":"И сказал ему Иисус: Истинно говорю тебе:\nсегодня со Мною будешь в раю.","44":"И было уже около шестого часа, и тьма\nнаступила по всей земле до часа девятого,","45":"так как не стало солнца. И разорвалась завеса\nхрама посредине.","46":"И возгласив громким голосом, Иисус сказал:\nОтче, в руки Твои предаю дух Мой. И сказав это,\nиспустил последний вздох.","47":"Увидев же происшедшее, сотник прославлял\nБога, говоря: действительно, Человек Этот праведен\nбыл.","48":"И весь народ, собравшийся на это зрелище,\nувидев происшедшее, возвращался, бия себя в грудь.","49":"Стояли же поодаль все знавшие Его, и женщины,\nпоследовавшие за Ним из Галилеи, видели это.","50":"И вот муж, по имени Иосиф, член совета, муж\nдобрый и праведный –","51":"он не был согласен с решением и делом их, – из\nАримафеи, города Иудейского. Он ожидал Царства\nБожия.","52":"Явившись к Пилату, он попросил тело Иисуса.","53":"И сняв, обернул тело полотном и положил Иисуса\nв гробнице, высеченной в скале, где еще никто никогда\nне лежал.","54":"А день был пятница, и наступала суббота.","55":"И пойдя следом, женщины, вместе с Иисусом\nпришедшие из Галилеи, видели гробницу, и как\nположено было тело Его.","56":"И возвратившись, приготовили благовония и\nмиро. И субботу они провели в покое по заповеди,"},"24":{"1":"а в первый день недели ранним утром пришли к\nгробнице, неся приготовленные ими благовония.","2":"И нашли они камень отваленным от гробницы","3":"и, войдя, не нашли тела Господа Иисуса.","4":"И было: когда они недоумевали об этом, вот\nпредстали им два мужа в одеянии блистающем.","5":"Когда же они устрашились и склоняли лица к\nземле, те сказали им: что вы ищете живого среди\nмертвых?","6":"Его нет здесь, но восстал Он. Вспомните, как Он\nсказал вам, когда был еще в Галилее,","7":"говоря о Сыне Человеческом, что надлежит Ему\nбыть преданным в руки людей грешных и быть\nраспятым и в третий день воскреснуть.","8":"И вспомнили они слова Его","9":"и, возвратившись от гробницы, возвестили всё это\nодиннадцати и всем прочим.","10":"То были Магдалина Мария и Иоанна и Мария\nИаковлева. И другие с ними говорили апостолам об\nэтом.","11":"И показались им слова эти бредом, и они не\nверили женщинам.","12":"Но\nПетр,\nвстав,\nпобежал\nк\nгробнице\nи,\nнаклонившись, видит одни только пелены. И пошел он к\nсебе, дивясь происшедшему.","13":"И вот, двое из них в тот же день шли в селение,\nотстоящее в шестидесяти стадиях от Иерусалима, имя\nему Эммаус.","14":"И они беседовали между собой о всех этих\nсобытиях.","15":"И было: когда они беседовали и рассуждали, Сам\nИисус, приблизившись, пошел с ними;","16":"но глаза их были удержаны, так что они не\nузнали Его.","17":"Он же сказал им: о чем это вы толкуете между\nсобою в пути? И они остановились омраченные.","18":"А один из них, по имени Клеопа, сказал Ему в\nответ: один Ты в Иерусалиме не знаешь о случившемся\nв нем в эти дни?","19":"И сказал им: о чем? Они же сказали Ему: о том,\nчто было с Иисусом Назарянином, Который был пророк,\nсильный в деле и слове пред Богом и всем народом;","20":"как предали Его первосвященники и начальники\nнаши для осуждения на смерть и распяли Его.","21":"А мы надеялись, что Он есть Тот, Который\nдолжен избавить Израиля. Но и при всём том, идет\nтретий день с тех пор, как это произошло.","22":"Но и некоторые из наших женщин изумили нас:\nпридя рано утром к гробнице,","23":"и не найдя тела Его, они пришли, говоря, что\nвидели и явление ангелов, которые говорят, что Он\nжив.","24":"И пошли некоторые из тех, что с нами, к\nгробнице и нашли так, как и женщины сказали. Его же\nне видели.","25":"И Он сказал им: о несмысленные и медлительные\nсердцем, чтобы верить во всё, что сказали пророки!","26":"Не это ли надлежало претерпеть Христу и войти\nв славу Свою?","27":"И начав от Моисея и от всех Пророков,\nистолковал им во всех Писаниях то, что относится к\nНему.","28":"И приблизились они к тому селению, куда шли; и\nОн сделал вид, что идет дальше.","29":"Но они понуждали Его, говоря: останься с нами,\nпотому что наступает вечер, и день уже на склоне. И Он\nвошел, чтобы остаться с ними.","30":"И было: когда Он возлег с ними, то, взяв хлеб,\nблагословил и, преломив, давал им.","31":"И у них открылись глаза, и они узнали Его, и Он\nстал невидим для них.","32":"И сказали они друг другу: не горело ли в нас\nсердце наше, когда Он говорил нам в пути, когда Он\nоткрывал нам Писания?","33":"И встав в тот же час, они возвратились в\nИерусалим и нашли вместе одиннадцать и тех, что с\nними,","34":"которые говорили, что Господь действительно\nвосстал и явился Симону.","35":"И они рассказывали о том, что было в пути, и как\nОн был узнан ими в преломлении хлеба.","36":"А когда они говорили об этом. Он Сам стал\nпосреди них, и говорит им: мир вам.","37":"Они же, в ужасе и страхе, думали, что видят\nдуха.","38":"И Он сказал им: почему вы смущены, и отчего\nсомнения возникают в сердце вашем?","39":"Посмотрите на руки Мои и на ноги Мои; это Я\nСам; осяжите Меня и посмотрите: дух плоти и костей не\nимеет, как вы видите у Меня.","40":"И сказав это, Он показал им руки и ноги.","41":"Когда же они от радости еще не верили и\nудивлялись, Он сказал им: есть ли у вас здесь какая\nпища?","42":"И они подали Ему кусок печеной рыбы.","43":"И взяв, он перед ними съел.","44":"И сказал им: вот слова Мои, которые Я говорил\nвам, когда еще был с вами, что надлежит исполниться\nвсему, написанному в Законе Моисеевом и в Пророках и\nПсалмах о Мне.","45":"Тогда Он открыл им ум для разумения Писаний.","46":"И сказал им: так написано, чтобы Христу\nпострадать и воскреснуть из мертвых в третий день,","47":"и чтобы было проповедано во имя Его покаяние\nдля отпущения грехов во всех народах, начиная с\nИерусалима.","48":"Вы свидетели этому.","49":"И вот, Я посылаю обещанное Отцом Моим на вас.\nВы же оставайтесь в городе этом, доколе не облечетесь\nсилою свыше.","50":"И вывел их из города до Вифании и, подняв руки\nСвои, благословил их.","51":"И было: когда благословлял их, Он отделился от\nних и стал возноситься на небо.","52":"И они, поклонившись Ему, возвратились в\nИерусалим с радостью великою,","53":"и были постоянно в храме, благословляя Бога."}};
